import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getRouteInsights = async (routeName: string, location: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Provide 3 safety tips and 1 scenic highlight for a motorcycle trip named "${routeName}" near ${location}. Return as JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            safetyTips: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            scenicHighlight: { type: Type.STRING }
          },
          required: ["safetyTips", "scenicHighlight"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Error:", error);
    return null;
  }
};

