import React, { useEffect, useRef } from 'react';
import { RoutePoint } from '../types';

interface MapViewProps {
  points: RoutePoint[];
  className?: string;
  isInteractive?: boolean;
}

export const MapView: React.FC<MapViewProps> = ({ points, className = "h-64", isInteractive = false }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<any>(null);

  useEffect(() => {
    // Only load if L exists (added via CDN in index.html)
    const L = (window as any).L;
    if (!L || !mapRef.current || leafletMap.current) return;

    leafletMap.current = L.map(mapRef.current, {
      zoomControl: isInteractive,
      dragging: isInteractive,
      scrollWheelZoom: isInteractive,
      attributionControl: false,
    }).setView([-23.5505, -46.6333], 13);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 19,
    }).addTo(leafletMap.current);

    return () => {
      if (leafletMap.current) {
        leafletMap.current.remove();
        leafletMap.current = null;
      }
    };
  }, [isInteractive]);

  useEffect(() => {
    const L = (window as any).L;
    if (!L || !leafletMap.current || points.length === 0) return;

    // Clear existing layers if any (except base)
    leafletMap.current.eachLayer((layer: any) => {
      if (layer instanceof L.Polyline || layer instanceof L.Marker) {
        leafletMap.current.removeLayer(layer);
      }
    });

    const latLngs = points.map(p => [p.lat, p.lng]);
    const polyline = L.polyline(latLngs, { color: '#eab308', weight: 4 }).addTo(leafletMap.current);

    // Fit bounds
    leafletMap.current.fitBounds(polyline.getBounds(), { padding: [20, 20] });

    // Markers for start and end
    L.circleMarker(latLngs[0], { radius: 5, color: '#eab308', fillOpacity: 1 }).addTo(leafletMap.current);
    if (latLngs.length > 1) {
      L.circleMarker(latLngs[latLngs.length - 1], { radius: 5, color: '#ef4444', fillOpacity: 1 }).addTo(leafletMap.current);
    }
  }, [points]);

  return (
    <div ref={mapRef} className={`rounded-xl overflow-hidden border border-zinc-800 ${className}`} />
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Play, Square, MapPin, Gauge, Clock, Radio } from 'lucide-react';
import { RoutePoint } from '../types';
import { MapView } from './MapView';

export const RouteTracker: React.FC = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [points, setPoints] = useState<RoutePoint[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    let interval: any;
    if (isRecording && startTime) {
      interval = setInterval(() => {
        setElapsed(Math.floor((Date.now() - startTime) / 1000));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isRecording, startTime]);

  const startTracking = () => {
    if (!navigator.geolocation) {
      alert("Geolocalização não suportada pelo seu navegador.");
      return;
    }

    setIsRecording(true);
    setStartTime(Date.now());
    setPoints([]);

    watchId.current = navigator.geolocation.watchPosition(
      (pos) => {
        const newPoint = {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          timestamp: pos.timestamp,
        };
        setPoints(prev => [...prev, newPoint]);
      },
      (err) => console.error(err),
      { enableHighAccuracy: true }
    );
  };

  const stopTracking = () => {
    if (watchId.current !== null) {
      navigator.geolocation.clearWatch(watchId.current);
    }
    setIsRecording(false);
    setStartTime(null);
    setElapsed(0);
    alert("Rota registrada e salva com sucesso na sua garagem!");
  };

  const formatTime = (sec: number) => {
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = sec % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6">
      <header>
        <h2 className="text-3xl font-oswald font-bold uppercase tracking-tight text-white flex items-center gap-2">
          <Radio className={isRecording ? "text-red-600 animate-pulse" : "text-zinc-500"} />
          Gravando <span className="text-yellow-500">Percurso</span>
        </h2>
        <p className="text-zinc-400">Registre sua jornada em tempo real pelas estradas.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <MapView points={points} className="h-[500px]" isInteractive />
        </div>

        <div className="space-y-6">
          <div className="bg-zinc-900 p-6 rounded-2xl border border-zinc-800 space-y-4 shadow-xl">
            <div className="flex items-center justify-between">
              <span className="text-zinc-500 flex items-center gap-2"><Clock size={18} className="text-yellow-500" /> Tempo</span>
              <span className="text-2xl font-mono text-white font-bold">{formatTime(elapsed)}</span>
            </div>
            <div className="flex items-center justify-between border-t border-zinc-800 pt-4">
              <span className="text-zinc-500 flex items-center gap-2"><Gauge size={18} className="text-red-600" /> Distância</span>
              <span className="text-2xl font-mono text-white font-bold">{(points.length * 0.05).toFixed(2)} km</span>
            </div>
            <div className="flex items-center justify-between border-t border-zinc-800 pt-4">
              <span className="text-zinc-500 flex items-center gap-2"><MapPin size={18} className="text-yellow-500" /> Pontos</span>
              <span className="text-2xl font-mono text-white font-bold">{points.length}</span>
            </div>
          </div>

          {!isRecording ? (
            <button
              onClick={startTracking}
              className="w-full bg-yellow-500 hover:bg-yellow-600 text-black py-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-yellow-500/10"
            >
              <Play fill="currentColor" size={20} /> INICIAR GRAVAÇÃO
            </button>
          ) : (
            <button
              onClick={stopTracking}
              className="w-full bg-red-600 hover:bg-red-700 text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-red-600/10"
            >
              <Square fill="currentColor" size={20} /> FINALIZAR E SALVAR
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

