const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [insights, setInsights] = useState<any>(null);
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    checkUser();
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
    }
  }, [isAuthenticated]);

  const checkUser = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user) {
      setUser({
        id: session.user.id,
        name: session.user.user_metadata?.name || 'Membro L.A.M.A.',
        email: session.user.email || '',
        bikeModel: session.user.user_metadata?.bikeModel || 'Não informado',
        avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${session.user.id}`
      });
      setIsAuthenticated(true);
    }
    setIsLoading(false);
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      setRoutes(data);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { data, error } = await supabase.auth.signInWithPassword({
      email: loginForm.email,
      password: loginForm.password,
    });

    if (error) {
      alert("Erro no login: " + error.message);
      setIsLoading(false);
      return;
    }

    if (data.user) {
      checkUser();
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
    setUser(null);
    setView('home');
  };

  const handleSaveRoute = async (newRoute: Route) => {
    const { error } = await supabase
      .from('routes')
      .insert([{
        ...newRoute,
        user_id: user?.id
      }]);

    if (error) {
      console.error("Erro ao salvar rota no Supabase:", error);
    } else {
      fetchRoutes();
    }
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func: command, args: [] }),
        '*'
      );
      setIsMuted(!isMuted);
    }
  };

  const toggleFullScreen = () => {
    if (videoRef.current) {
      if (videoRef.current.requestFullscreen) {
        videoRef.current.requestFullscreen();
      } else if ((videoRef.current as any).webkitRequestFullscreen) {
        (videoRef.current as any).webkitRequestFullscreen();
      }
    }
  };

  const fetchInsights = async (route: Route) => {
    setInsights('carregando');
    const data = await getRouteInsights(route.title, 'Aparecida de Goiânia, Brasil');
    setInsights(data);
  };

  const getDifficultyBadge = (difficulty: string) => {
    let colorClass = "";
    switch (difficulty) {
      case 'Lendária':
      case 'Difícil': colorClass = "bg-red-600 text-white"; break;
      case 'Moderada': colorClass = "bg-orange-400 text-black"; break;
      case 'Fácil': colorClass = "bg-green-600 text-white"; break;
      default: colorClass = "bg-zinc-800 text-zinc-300";
    }
    return (
      <span className={`${colorClass} px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest shadow-lg inline-block`}>
        {difficulty}
      </span>
    );
  };

  const publicViews: View[] = ['home', 'clubhouse'];
  const needsAuth = !isAuthenticated && !publicViews.includes(currentView);

  if (isLoading && !isAuthenticated) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-6">
        <Loader2 className="text-yellow-500 animate-spin" size={48} />
        <p className="text-yellow-500 font-oswald font-bold uppercase tracking-widest animate-pulse">Autenticando com o Radar...</p>
      </div>
    );
  }

  const renderLogin = () => (
    <div className="min-h-[70vh] flex items-center justify-center p-4 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-full max-w-md bg-zinc-900/80 border border-zinc-800 p-8 md:p-12 rounded-[2.5rem] shadow-2xl backdrop-blur-xl">
        <div className="flex justify-center mb-8">
          <div className="p-4 bg-yellow-500/10 rounded-full border border-yellow-500/20">
            <Lock className="text-yellow-500" size={32} />
          </div>
        </div>
        <div className="text-center mb-10">
          <h2 className="text-2xl md:text-3xl font-oswald text-white font-black uppercase italic tracking-tighter">Área Restrita</h2>
          <p className="text-zinc-500 text-[10px] mt-2 uppercase tracking-widest font-black">Identifique-se via Supabase Auth</p>
        </div>
        <form onSubmit={handleLogin} className="space-y-5">
          <div className="space-y-2">
            <label className="text-[9px] font-black uppercase tracking-[0.3em] text-zinc-600 ml-4">Membro / Email</label>
            <input
              type="email"
              required
              className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl focus:ring-2 focus:ring-yellow-500/50 outline-none transition-all placeholder:text-zinc-800"
              placeholder="membro@lama.com"
              value={loginForm.email}
              onChange={e => setLoginForm({...loginForm, email: e.target.value})}
            />
          </div>
          <div className="space-y-2">
            <label className="text-[9px] font-black uppercase tracking-[0.3em] text-zinc-600 ml-4">Senha de Acesso</label>
            <input
              type="password"
              required
              className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl focus:ring-2 focus:ring-yellow-500/50 outline-none transition-all placeholder:text-zinc-800"
              placeholder="••••••••"
              value={loginForm.password}
              onChange={e => setLoginForm({...loginForm, password: e.target.value})}
            />
          </div>
          <button type="submit" disabled={isLoading} className="w-full bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-[0.2em] text-xs transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3">
            {isLoading ? <Loader2 className="animate-spin" size={16} /> : <>Entrar no Capítulo <Zap size={16} /></>}
          </button>
        </form>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#050505] text-zinc-300">
      <Sidebar 
        currentView={currentView} 
        setView={setView} 
        onLogout={handleLogout} 
      />

