const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'signup'>('login');

  const [loginForm, setLoginForm] = useState({ email: '', password: '', name: '', bikeModel: '' });
  const [editForm, setEditForm] = useState({ name: '', bikeModel: '', avatar: '' });
  const [insights, setInsights] = useState<any>(null);
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    checkUser();
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
    }
  }, [isAuthenticated]);

  const checkUser = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user) {
      const userData = {
        id: session.user.id,
        name: session.user.user_metadata?.name || 'Membro L.A.M.A.',
        email: session.user.email || '',
        bikeModel: session.user.user_metadata?.bikeModel || 'Não informado',
        avatar: session.user.user_metadata?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${session.user.id}`
      };
      setUser(userData);
      setEditForm({
        name: userData.name,
        bikeModel: userData.bikeModel || '',
        avatar: userData.avatar || ''
      });
      setIsAuthenticated(true);
    }
    setIsLoading(false);
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      setRoutes(data);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    if (authMode === 'login') {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: loginForm.email,
        password: loginForm.password,
      });

      if (error) {
        alert("Erro no login: " + error.message);
        setIsLoading(false);
        return;
      }
      if (data.user) checkUser();
    } else {
      const { data, error } = await supabase.auth.signUp({
        email: loginForm.email,
        password: loginForm.password,
        options: {
          data: {
            name: loginForm.name,
            bikeModel: loginForm.bikeModel
          }
        }
      });

      if (error) {
        alert("Erro no cadastro: " + error.message);
        setIsLoading(false);
        return;
      }
      alert("Cadastro realizado! Verifique seu email ou faça login.");
      setAuthMode('login');
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    const { data, error } = await supabase.auth.updateUser({
      data: {
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      }
    });

    if (error) {
      alert("Erro ao atualizar: " + error.message);
    } else {
      setUser({
        ...user!,
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      });
      setIsEditingProfile(false);
    }
    setIsUpdating(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
    setUser(null);
    setView('home');
  };

  const handleSaveRoute = async (newRoute: Route) => {
    const { error } = await supabase
      .from('routes')
      .insert([{
        ...newRoute,
        user_id: user?.id
      }]);

    if (error) {
      console.error("Erro ao salvar rota no Supabase:", error);
    } else {
      fetchRoutes();
    }
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func: command, args: [] }),
        '*'
      );
      setIsMuted(!isMuted);
    }
  };

  const toggleFullScreen = () => {
    if (videoRef.current) {
      if (videoRef.current.requestFullscreen) {
        videoRef.current.requestFullscreen();
      } else if ((videoRef.current as any).webkitRequestFullscreen) {
        (videoRef.current as any).webkitRequestFullscreen();
      }
    }
  };

  const fetchInsights = async (route: Route) => {
    setInsights('carregando');
    const data = await getRouteInsights(route.title, 'Aparecida de Goiânia, Brasil');
    setInsights(data);
  };

  const getDifficultyBadge = (difficulty: string) => {
    let colorClass = "";
    switch (difficulty) {
      case 'Lendária':
      case 'Difícil': colorClass = "bg-red-600 text-white"; break;
      case 'Moderada': colorClass = "bg-orange-400 text-black"; break;
      case 'Fácil': colorClass = "bg-green-600 text-white"; break;
      default: colorClass = "bg-zinc-800 text-zinc-300";
    }
    return (
      <span className={`${colorClass} px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest shadow-lg inline-block`}>
        {difficulty}
      </span>
    );
  };

  const publicViews: View[] = ['home', 'clubhouse'];
  const needsAuth = !isAuthenticated && !publicViews.includes(currentView);

  if (isLoading && !isAuthenticated) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-6">
        <Loader2 className="text-yellow-500 animate-spin" size={48} />
        <p className="text-yellow-500 font-oswald font-bold uppercase tracking-widest animate-pulse">Autenticando Capítulo...</p>
      </div>
    );
  }

  const renderLogin = () => (
    <div className="min-h-[70vh] flex items-center justify-center p-4 animate-in fade-in zoom-in-95 duration-700">
      <div className="w-full max-w-md bg-zinc-900/80 border border-zinc-800 p-8 md:p-12 rounded-[2.5rem] shadow-2xl backdrop-blur-xl">
        <div className="flex justify-center mb-8">
          <div className="p-4 bg-yellow-500/10 rounded-full border border-yellow-500/20">
            {authMode === 'login' ? <Lock className="text-yellow-500" size={32} /> : <UserPlus className="text-yellow-500" size={32} />}
          </div>
        </div>
        <div className="text-center mb-10">
          <h2 className="text-2xl md:text-3xl font-oswald text-white font-black uppercase italic tracking-tighter">
            {authMode === 'login' ? 'Acesso ao Capítulo' : 'Recrutamento Online'}
          </h2>
          <p className="text-zinc-500 text-[10px] mt-2 uppercase tracking-widest font-black">L.A.M.A. Aparecida & Supabase</p>
        </div>
        <form onSubmit={handleAuth} className="space-y-4">
          {authMode === 'signup' && (
            <>
              <div className="space-y-1">
                <label className="text-[8px] font-black uppercase tracking-[0.3em] text-zinc-600 ml-4">Nome de Estrada</label>
                <input
                  type="text"
                  required
                  className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none transition-all placeholder:text-zinc-800 text-sm"
                  placeholder="Seu Nome / Apelido"
                  value={loginForm.name}
                  onChange={e => setLoginForm({...loginForm, name: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black uppercase tracking-[0.3em] text-zinc-600 ml-4">Modelo da Moto</label>
                <input
                  type="text"
                  className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none transition-all placeholder:text-zinc-800 text-sm"
                  placeholder="Ex: BMW GS 1250"
                  value={loginForm.bikeModel}
                  onChange={e => setLoginForm({...loginForm, bikeModel: e.target.value})}
                />
              </div>
            </>
          )}
          <div className="space-y-1">
            <label className="text-[8px] font-black uppercase tracking-[0.3em] text-zinc-600 ml-4">Email</label>
            <input
              type="email"
              required
              className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none transition-all placeholder:text-zinc-800 text-sm"
              placeholder="membro@lama.com"
              value={loginForm.email}
              onChange={e => setLoginForm({...loginForm, email: e.target.value})}
            />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] font-black uppercase tracking-[0.3em] text-zinc-600 ml-4">Senha</label>
            <input
              type="password"
              required
              className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none transition-all placeholder:text-zinc-800 text-sm"
              placeholder="••••••••"
              value={loginForm.password}
              onChange={e => setLoginForm({...loginForm, password: e.target.value})}
            />
          </div>

          <button type="submit" disabled={isLoading} className="w-full bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-[0.2em] text-xs transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3 mt-4">
            {isLoading ? <Loader2 className="animate-spin" size={16} /> : (authMode === 'login' ? <>Entrar <Zap size={16} /></> : <>Finalizar Cadastro <Users size={16} /></>)}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button 
            onClick={() => setAuthMode(authMode === 'login' ? 'signup' : 'login')}
            className="text-zinc-500 hover:text-yellow-500 text-[10px] font-black uppercase tracking-widest transition-colors"
          >
            {authMode === 'login' ? 'Não tem conta? Cadastre-se' : 'Já é membro? Faça Login'}
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#050505] text-zinc-300">
      <Sidebar 
        currentView={currentView} 
        setView={setView} 
        onLogout={handleLogout} 
      />

      <main className="flex-1 p-5 md:p-12 pb-24 md:pb-12 max-w-[1400px] mx-auto w-full overflow-y-auto custom-scrollbar">
        {needsAuth ? renderLogin() : (
          <div className="animate-in fade-in duration-700">
            {currentView === 'home' && (
              <div className="space-y-12 md:space-y-20">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-zinc-900 pb-8 md:pb-16">
                  <div className="flex items-center gap-6 md:gap-10">
                    <div className="relative group">
                      <div className="absolute inset-0 bg-yellow-500/10 blur-[40px] rounded-full"></div>
                      <img src={LAMA_LOGO_URL} alt="Logo" className="relative w-16 h-16 md:w-28 md:h-28 object-contain" />
                    </div>
                    <div>
                      <div className="flex items-center mb-1">
                        <span className="text-yellow-500 font-black uppercase tracking-[0.2em] text-[10px] md:text-lg">LATIN AMERICAN MOTORCYCLE ASSOCIATION</span>
                      </div>
                      <h1 className="text-2xl md:text-5xl font-oswald font-black text-white uppercase italic tracking-tighter leading-[0.8] mt-2">
                        Capítulo <span className="text-yellow-500">Aparecida</span>
                      </h1>
                    </div>
                  </div>
                </header>

                <section className="relative rounded-[2.5rem] md:rounded-[4rem] overflow-hidden bg-zinc-900 border border-zinc-800 aspect-[4/5] md:aspect-[21/9] shadow-3xl group">
                  <div className="absolute inset-0 z-10 pointer-events-none bg-gradient-to-t from-black via-transparent to-transparent"></div>
                  <iframe 
                    ref={videoRef}
                    className="w-full h-full object-cover opacity-60 transition-all duration-1000 scale-110 group-hover:scale-100"
                    src={`https://www.youtube.com/embed/${YOUTUBE_ID}?autoplay=1&mute=1&loop=1&playlist=${YOUTUBE_ID}&controls=0&modestbranding=1&rel=0&showinfo=0&iv_load_policy=3&enablejsapi=1`} 
                    frameBorder="0"
                    allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                  ></iframe>
                  <div className="absolute inset-0 z-20 p-5 md:p-16 flex flex-col justify-between pointer-events-none">
                    <div className="space-y-4 md:space-y-6">
                      <h3 className="text-4xl md:text-7xl font-oswald font-black text-white uppercase italic tracking-tighter leading-none">Respeito <span className="text-yellow-500">& Liberdade.</span></h3>
                      <p className="text-zinc-400 max-w-2xl text-sm md:text-xl leading-relaxed font-light">Conectado ao ecossistema Supabase para máxima performance.</p>
                    </div>

                    <div className="flex flex-row gap-2 md:gap-4 pointer-events-auto items-center mt-auto">
                       <button onClick={() => setView('clubhouse')} className="flex-1 md:flex-none bg-white text-black px-4 md:px-12 py-3.5 md:py-5 rounded-xl md:rounded-[1.8rem] font-black uppercase tracking-[0.15em] md:tracking-[0.2em] text-[9px] md:text-[11px] hover:bg-yellow-500 transition-all shadow-2xl truncate">Visitar Sede</button>
                       <button onClick={toggleMute} className="bg-zinc-900/80 backdrop-blur-md text-white p-3.5 md:p-5 rounded-xl md:rounded-[1.5rem] hover:bg-yellow-500 hover:text-black transition-all shadow-2xl border border-white/10 shrink-0">{isMuted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
                       <button onClick={toggleFullScreen} className="bg-zinc-900/80 backdrop-blur-md text-white p-3.5 md:p-5 rounded-xl md:rounded-[1.5rem] hover:bg-yellow-500 hover:text-black transition-all shadow-2xl border border-white/10 shrink-0"><Maximize2 size={18} /></button>
                    </div>
                  </div>
                </section>

                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-10">
                  {[
                    { icon: Users, label: 'Membros', value: '18', color: 'text-yellow-500' },
                    { icon: Compass, label: 'Km Rodados', value: `${(routes.reduce((acc, r) => acc + parseFloat(r.distance || '0'), 0)).toFixed(1)}k`, color: 'text-red-600' },
                    { icon: Calendar, label: 'Missões', value: routes.length.toString(), color: 'text-yellow-500' },
                    { icon: Trophy, label: 'Anos', value: '03', color: 'text-red-600' },
                  ].map((stat, i) => (
                    <div key={i} className="bg-zinc-900/30 border border-zinc-900/50 p-4 md:p-10 rounded-2xl md:rounded-[3rem] backdrop-blur-sm">
                      <stat.icon size={16} className={`${stat.color} mb-3 md:mb-4`} />
                      <p className="text-2xl md:text-5xl font-oswald font-black text-white italic tracking-tighter leading-none">{stat.value}</p>
                      <p className="text-zinc-600 text-[8px] md:text-[11px] uppercase font-black tracking-[0.3em] mt-1 md:mt-2">{stat.label}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {currentView === 'clubhouse' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4 md:gap-6">
                   <div className="w-2 md:w-3 h-10 md:h-14 bg-yellow-500 rounded-full"></div>
                   <h2 className="text-4xl md:text-6xl font-oswald font-black text-white italic uppercase tracking-tighter">Casa <span className="text-yellow-500">Club</span></h2>
                </header>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 md:gap-16">
                  <div className="space-y-10 order-2 lg:order-1">
                    <div className="bg-zinc-950 p-10 md:p-16 rounded-[3rem] border border-zinc-900 relative overflow-hidden shadow-3xl">
                      <div className="absolute top-0 right-0 p-10 opacity-5"><MapPin size={120} /></div>
                      <div className="relative z-10 space-y-8">
                        <div className="flex items-center gap-4">
                          <div className="bg-yellow-500 p-3 rounded-2xl"><Shield size={24} className="text-black" /></div>
                          <span className="text-zinc-600 font-black uppercase text-[10px] tracking-widest">Sede Oficial Aparecida</span>
                        </div>
                        <h3 className="text-4xl md:text-5xl font-oswald font-black text-white uppercase italic tracking-tighter leading-none">Ponto de <span className="text-yellow-500">Encontro</span></h3>
                        <p className="text-zinc-400 text-lg md:text-xl font-light leading-relaxed">{CLUBHOUSE_ADDRESS}</p>
