        name: session.user.user_metadata?.name || 'Membro L.A.M.A.',
        email: session.user.email || '',
        bikeModel: session.user.user_metadata?.bikeModel || 'Não informado',
        avatar: session.user.user_metadata?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${session.user.id}`,
        role: session.user.user_metadata?.role || 'member'
      };
      setUser(userData);
      setEditForm({
        name: userData.name,
        bikeModel: userData.bikeModel || '',
        avatar: userData.avatar || ''
      });
      setIsAuthenticated(true);
    }
    setIsLoading(false);
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      setRoutes(data);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { data, error } = await supabase.auth.signInWithPassword({
      email: loginForm.email,
      password: loginForm.password,
    });

    if (error) {
      alert("Erro no login: " + error.message);
      setIsLoading(false);
      return;
    }
    if (data.user) checkUser();
  };

  const handleRegisterNewMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    // Nota: Criar usuários via API de cliente desloga o admin. 
    // Em uma aplicação real, usaríamos o Dashboard do Supabase. 
    // Para conveniência do Admin, recomendamos usar o Painel do Supabase > Auth > Users.
    const { data, error } = await supabase.auth.signUp({
      email: newMemberForm.email,
      password: newMemberForm.password,
      options: {
        data: {
          name: newMemberForm.name,
          bikeModel: newMemberForm.bikeModel,
          role: 'member'
        }
      }
    });

    if (error) {
      alert("Erro ao cadastrar: " + error.message);
    } else {
      alert(`Membro ${newMemberForm.name} cadastrado! Você será deslogado para confirmar a segurança.`);
      handleLogout();
    }
    setIsUpdating(false);
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      data: {
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      }
    });

    if (error) {
      alert("Erro ao atualizar: " + error.message);
    } else {
      setUser({
        ...user!,
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      });
      setIsEditingProfile(false);
      alert("Perfil atualizado com sucesso!");
    }
    setIsUpdating(false);
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      alert("As senhas não coincidem!");
      return;
    }
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      password: passwordForm.newPassword
    });

    if (error) {
      alert("Erro ao trocar senha: " + error.message);
    } else {
      alert("Senha alterada com sucesso! Use a nova senha no próximo login.");
      setIsChangingPassword(false);
      setPasswordForm({ newPassword: '', confirmPassword: '' });
    }
    setIsUpdating(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
    setUser(null);
    setView('home');
  };

  const handleSaveRoute = async (newRoute: Route) => {
    const { error } = await supabase
      .from('routes')
      .insert([{
        ...newRoute,
        user_id: user?.id
      }]);

    if (error) console.error("Erro ao salvar rota:", error);
    else fetchRoutes();
  };

  const fetchInsights = async (route: Route) => {
    setInsights('carregando');
    const result = await getRouteInsights(route.title, "Brasil");
    setInsights(result);
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: [] }), '*');
      setIsMuted(!isMuted);
    }
  };

  const renderLogin = () => (
    <div className="min-h-[70vh] flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-zinc-900/90 border border-zinc-800 p-12 rounded-[2.5rem] shadow-2xl backdrop-blur-xl">
        <div className="text-center mb-10">
          <img src={LAMA_LOGO_URL} alt="Logo" className="w-24 h-24 mx-auto mb-6" />
          <h2 className="text-3xl font-oswald text-white font-black uppercase italic tracking-tighter">Sede Virtual</h2>
          <p className="text-zinc-500 text-[10px] mt-2 uppercase tracking-widest font-black">Acesso Restrito a Membros</p>
        </div>
        <form onSubmit={handleLogin} className="space-y-4">
          <input
            type="email"
            required
            className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none placeholder:text-zinc-800"
            placeholder="membro@lama.com"
            value={loginForm.email}
            onChange={e => setLoginForm({...loginForm, email: e.target.value})}
          />
          <input
            type="password"
            required
            className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none placeholder:text-zinc-800"
            placeholder="Senha"
            value={loginForm.password}
            onChange={e => setLoginForm({...loginForm, password: e.target.value})}
          />
          <button type="submit" disabled={isLoading} className="w-full bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3">
            {isLoading ? <Loader2 className="animate-spin" size={16} /> : <>Entrar na Sede <Zap size={16} /></>}
          </button>
        </form>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#050505] text-zinc-300">
      <Sidebar currentView={currentView} setView={setView} onLogout={handleLogout} />

      <main className="flex-1 p-5 md:p-12 pb-24 md:pb-12 max-w-[1400px] mx-auto w-full overflow-y-auto">
        {!isAuthenticated ? renderLogin() : (
          <div className="animate-in fade-in duration-700">

            {currentView === 'home' && (
              <div className="space-y-12">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-zinc-900 pb-16">
                  <div className="flex items-center gap-10">
                    <img src={LAMA_LOGO_URL} alt="Logo" className="w-28 h-28 object-contain" />
                    <div>
                      <span className="text-yellow-500 font-black uppercase tracking-widest text-lg">LATIN AMERICAN MOTORCYCLE ASSOCIATION</span>
                      <h1 className="text-5xl font-oswald font-black text-white uppercase italic mt-2">Capítulo <span className="text-yellow-500">Aparecida</span></h1>
                    </div>
                  </div>
                </header>
                <section className="relative rounded-[4rem] overflow-hidden bg-zinc-900 border border-zinc-800 aspect-[21/9] shadow-3xl group">
                  <iframe 
                    ref={videoRef}
                    className="w-full h-full object-cover opacity-60"
                    src={`https://www.youtube.com/embed/${YOUTUBE_ID}?autoplay=1&mute=1&loop=1&playlist=${YOUTUBE_ID}&controls=0&enablejsapi=1`} 
                    frameBorder="0"
                  ></iframe>
                  <div className="absolute inset-0 z-20 p-16 flex flex-col justify-end">
                    <h3 className="text-7xl font-oswald font-black text-white uppercase italic mb-8 leading-none">Respeito <span className="text-yellow-500">& Liberdade.</span></h3>
                    <div className="flex gap-4">
                       <button onClick={() => setView('clubhouse')} className="bg-white text-black px-12 py-5 rounded-[1.8rem] font-black uppercase text-[11px] hover:bg-yellow-500 transition-all">Visitar Sede</button>
                       <button onClick={toggleMute} className="bg-zinc-900/80 backdrop-blur-md text-white p-5 rounded-[1.5rem] hover:bg-yellow-500 hover:text-black transition-all">{isMuted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
                    </div>
                  </div>
                </section>
              </div>
            )}

            {currentView === 'admin' && user?.role === 'admin' && (
              <div className="max-w-4xl mx-auto space-y-12">
                <header className="flex items-center gap-4">
                  <div className="w-2 h-10 bg-yellow-500 rounded-full"></div>
                  <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Administração do <span className="text-yellow-500">Capítulo</span></h2>
                </header>
                <div className="bg-zinc-950 p-12 rounded-[3rem] border border-zinc-900 shadow-3xl">
                  <h3 className="text-2xl font-oswald font-black text-white uppercase mb-8 flex items-center gap-3"><UserPlus size={24} className="text-yellow-500" /> Cadastrar Novo Membro</h3>
                  <form onSubmit={handleRegisterNewMember} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Nome de Estrada</label>
                      <input type="text" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="Ex: Relâmpago" value={newMemberForm.name} onChange={e => setNewMemberForm({...newMemberForm, name: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Email Oficial</label>
                      <input type="email" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="membro@lama.com" value={newMemberForm.email} onChange={e => setNewMemberForm({...newMemberForm, email: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Motocicleta</label>
                      <input type="text" className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="Harley-Davidson Fat Boy" value={newMemberForm.bikeModel} onChange={e => setNewMemberForm({...newMemberForm, bikeModel: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Senha Provisória</label>
                      <input type="text" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="mudar123" value={newMemberForm.password} onChange={e => setNewMemberForm({...newMemberForm, password: e.target.value})} />
                    </div>
                    <button type="submit" disabled={isUpdating} className="md:col-span-2 bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl active:scale-95 flex items-center justify-center gap-3">
                      {isUpdating ? <Loader2 className="animate-spin" size={16} /> : <><Save size={16} /> Confirmar Cadastro</>}
                    </button>
                  </form>
                  <p className="mt-6 text-zinc-600 text-[10px] text-center uppercase font-black italic">O Admin será deslogado após o cadastro para segurança do sistema.</p>
                </div>
              </div>
            )}

            {currentView === 'profile' && (
              <div className="max-w-5xl mx-auto space-y-10">
                <header className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-2 h-10 bg-yellow-500 rounded-full"></div>
                    <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Área do <span className="text-yellow-500">Membro</span></h2>
                  </div>
                  <div className="flex gap-4">
                    <button onClick={() => setIsChangingPassword(!isChangingPassword)} className="flex items-center gap-2 px-6 py-3 bg-zinc-900 border border-zinc-800 rounded-xl hover:bg-red-600 hover:text-white transition-all text-[10px] font-black uppercase tracking-widest">
                      <Key size={14} /> Alterar Senha
                    </button>
                    <button onClick={() => setIsEditingProfile(!isEditingProfile)} className="flex items-center gap-2 px-6 py-3 bg-zinc-900 border border-zinc-800 rounded-xl hover:bg-yellow-500 hover:text-black transition-all text-[10px] font-black uppercase tracking-widest">
                      <Edit2 size={14} /> Editar Perfil
                    </button>
                  </div>
                </header>

                {isChangingPassword && (
                  <div className="bg-red-600/5 border border-red-600/20 p-10 rounded-[2.5rem] animate-in slide-in-from-top-4 duration-500">
                    <h3 className="text-2xl font-oswald font-black text-white uppercase mb-6 flex items-center gap-3"><Lock size={20} /> Segurança</h3>
                    <form onSubmit={handleChangePassword} className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <input type="password" required className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="Nova Senha" value={passwordForm.newPassword} onChange={e => setPasswordForm({...passwordForm, newPassword: e.target.value})} />
                      <input type="password" required className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="Confirme a Nova Senha" value={passwordForm.confirmPassword} onChange={e => setPasswordForm({...passwordForm, confirmPassword: e.target.value})} />
                      <button type="submit" disabled={isUpdating} className="sm:col-span-2 bg-red-600 hover:bg-red-500 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-xs">
                        {isUpdating ? <Loader2 className="animate-spin mx-auto" size={16} /> : "Atualizar Senha"}
                      </button>
                    </form>
                  </div>
                )}

                <div className="relative bg-zinc-950 p-16 rounded-[3rem] border border-zinc-900 shadow-3xl overflow-hidden">
                  {isEditingProfile ? (
                    <form onSubmit={handleUpdateProfile} className="space-y-8">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-2">
                          <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Nome de Estrada</label>
                          <input type="text" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" value={editForm.name} onChange={e => setEditForm({...editForm, name: e.target.value})} />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Motocicleta Principal</label>
                          <input type="text" className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" value={editForm.bikeModel} onChange={e => setEditForm({...editForm, bikeModel: e.target.value})} />
                        </div>
                        <div className="md:col-span-2 space-y-2">
                          <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">URL da Foto (Avatar)</label>
                          <input type="url" className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl" placeholder="https://imagem.com/foto.jpg" value={editForm.avatar} onChange={e => setEditForm({...editForm, avatar: e.target.value})} />
                        </div>
                      </div>
                      <div className="flex justify-end gap-4">
                        <button type="button" onClick={() => setIsEditingProfile(false)} className="px-8 py-4 text-zinc-500 font-black uppercase text-[10px]">Cancelar</button>
                        <button type="submit" className="bg-yellow-500 text-black px-12 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl">Salvar Alterações</button>
                      </div>
                    </form>
                  ) : (
                    <div className="flex flex-col md:flex-row items-center md:items-start gap-16">
                      <img src={user?.avatar} alt="Avatar" className="w-64 h-64 rounded-[2.5rem] border-4 border-zinc-950 object-cover shadow-2xl" />
                      <div className="flex-1 space-y-8 text-center md:text-left">
                        <div>
                          <span className="inline-block px-3 py-1 bg-yellow-500/10 text-yellow-500 text-[10px] font-black uppercase rounded-lg mb-4">Membro Oficial</span>
                          <h2 className="text-7xl font-oswald font-black text-white uppercase italic tracking-tighter leading-none mb-4">MEMBRO: <span className="text-yellow-500">{user?.name}</span></h2>
                          <p className="text-zinc-500 font-black uppercase tracking-widest text-xs italic">{user?.email}</p>
                        </div>
                        <div className="bg-zinc-900/40 p-8 rounded-[2rem] border border-zinc-900/50 inline-flex items-center gap-6">
                           <div className="p-4 bg-yellow-500/10 rounded-2xl"><Bike size={28} className="text-yellow-500" /></div>
                           <div className="text-left">
                              <span className="text-[9px] text-zinc-600 font-black uppercase tracking-widest">Máquina Principal</span>
                              <p className="font-bold text-white text-xl tracking-tight uppercase italic">{user?.bikeModel}</p>
                           </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {currentView === 'tracking' && <RouteTracker onSave={handleSaveRoute} />}

            {currentView === 'my-routes' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-red-600 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Minhas <span className="text-yellow-500">Missões</span></h2>
                </header>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  {routes.length > 0 ? routes.map(route => (
                    <div key={route.id} className="bg-zinc-950 rounded-[2.5rem] border border-zinc-900 overflow-hidden shadow-2xl">
                      <MapView points={route.points} className="h-48 border-none rounded-none" />
                      <div className="p-8">
                        <h3 className="text-2xl font-oswald font-black text-white uppercase italic tracking-tighter">{route.title}</h3>
                        <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest mt-2">{route.distance} Rodados</p>
                      </div>
                    </div>
                  )) : (
                    <div className="col-span-full py-20 text-center bg-zinc-900/20 rounded-[3rem] border border-dashed border-zinc-800 text-zinc-500 font-black uppercase italic">Nenhuma rota gravada.</div>
                  )}
                </div>
              </div>
            )}

            {currentView === 'clubhouse' && (
              <div className="space-y-12">
                <header className="flex items-center gap-6">
                   <div className="w-3 h-14 bg-yellow-500 rounded-full"></div>
                   <h2 className="text-6xl font-oswald font-black text-white italic uppercase tracking-tighter">Casa <span className="text-yellow-500">Club</span></h2>
                </header>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
                  <div className="bg-zinc-950 p-16 rounded-[3rem] border border-zinc-900 shadow-3xl">
                    <h3 className="text-4xl font-oswald font-black text-white uppercase italic mb-8">Ponto de <span className="text-yellow-500">Encontro</span></h3>
                    <p className="text-zinc-400 text-xl font-light leading-relaxed mb-10">{CLUBHOUSE_ADDRESS}</p>
                    <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(CLUBHOUSE_MARK_NAME)}`} target="_blank" className="bg-white text-black px-12 py-6 rounded-3xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-4 hover:bg-yellow-500 transition-all shadow-2xl">Abrir no Maps <ExternalLink size={20} /></a>
                  </div>
                  <MapView points={[{...CLUBHOUSE_COORDS, timestamp: Date.now()}]} className="h-[500px] shadow-3xl" isInteractive />
                </div>
              </div>
            )}

            {currentView === 'explorer' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-yellow-500 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Rotas <span className="text-yellow-500">Icônicas</span></h2>
                </header>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  {iconicRoutes.map(route => (
                    <div key={route.id} className="bg-zinc-950 rounded-[2.5rem] border border-zinc-900 overflow-hidden shadow-2xl flex flex-col">
                      <img src={route.thumbnail} className="h-64 object-cover" alt={route.title} />
                      <div className="p-10 flex-1">
                        <h3 className="text-3xl font-oswald font-black text-white uppercase italic tracking-tighter mb-4">{route.title}</h3>
                        <p className="text-zinc-500 text-sm leading-relaxed mb-8">{route.description}</p>
                        <button onClick={() => fetchInsights(route)} className="w-full bg-zinc-900 border border-zinc-800 text-yellow-500 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-yellow-500 hover:text-black transition-all">Ver Briefing AI</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {currentView === 'gallery' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-blue-500 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Nossa <span className="text-yellow-500">Galeria</span></h2>
                </header>
                <div className="bg-zinc-900/30 p-20 rounded-[4rem] border border-zinc-900 text-center space-y-8">
                   <ImageIcon size={64} className="text-yellow-500 mx-auto" />
                   <h3 className="text-4xl font-oswald font-black text-white uppercase italic">Registros no <span className="text-blue-500">Facebook</span></h3>
                   <a href="https://www.facebook.com/lamaaparecidabr/photos" target="_blank" className="inline-flex items-center gap-4 bg-yellow-500 text-black px-16 py-6 rounded-3xl font-black uppercase text-xs tracking-widest hover:bg-yellow-400 transition-all shadow-3xl">Acessar Álbuns Oficiais <ExternalLink size={20} /></a>
                </div>
              </div>
            )}

          </div>
        )}
      </main>

      {insights && insights !== 'carregando' && (
        <div className="fixed inset-0 z-[3000] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <div className="bg-zinc-950 border border-zinc-900 p-16 rounded-[3rem] max-w-2xl w-full relative shadow-3xl">
            <button onClick={() => setInsights(null)} className="absolute top-8 right-8 text-zinc-600 hover:text-white font-black">✕</button>
            <h3 className="text-3xl font-oswald font-black text-white uppercase italic mb-10">Briefing de <span className="text-yellow-500">Missão</span></h3>
            <div className="space-y-6">
              {insights.safetyTips.map((tip: string, i: number) => (
                <div key={i} className="p-6 bg-zinc-900/40 rounded-[1.5rem] border border-zinc-800/50 flex gap-4 text-zinc-300">
                  <span className="text-yellow-500 font-black italic text-xl">0{i+1}</span>
                  <p className="font-light">{tip}</p>
                </div>
              ))}
              <div className="p-8 bg-yellow-500/5 rounded-[2.5rem] border border-yellow-500/10 italic text-zinc-400 text-center leading-relaxed">"{insights.scenicHighlight}"</div>
            </div>
          </div>
        </div>
      )}

      {insights === 'carregando' && (
        <div className="fixed inset-0 z-[3000] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
          <div className="bg-zinc-950 border border-zinc-900 p-10 rounded-[2rem] flex flex-col items-center gap-4">
            <Loader2 className="animate-spin text-yellow-500" size={40} />
            <p className="text-white font-oswald font-black uppercase italic tracking-widest">Consultando IA...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

