                </header>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
                  <div className="bg-zinc-950 p-16 rounded-[3rem] border border-zinc-900 shadow-3xl">
                    <h3 className="text-4xl font-oswald font-black text-white uppercase italic mb-8">Ponto de <span className="text-yellow-500">Encontro</span></h3>
                    <p className="text-zinc-400 text-xl font-light leading-relaxed mb-10">{CLUBHOUSE_ADDRESS}</p>
                    <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(CLUBHOUSE_MARK_NAME)}`} target="_blank" rel="noopener noreferrer" className="bg-white text-black px-12 py-6 rounded-3xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-4 hover:bg-yellow-500 transition-all shadow-2xl">Abrir no Maps <ExternalLink size={20} /></a>
                  </div>
                  <MapView points={[{...CLUBHOUSE_COORDS, timestamp: Date.now()}]} className="h-[500px] shadow-3xl" isInteractive />
                </div>
              </div>
            )}

            {currentView === 'explorer' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-yellow-500 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Rotas <span className="text-yellow-500">Icônicas</span></h2>
                </header>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  {iconicRoutes.map(route => (
                    <div key={route.id} className="bg-zinc-950 rounded-[2.5rem] border border-zinc-900 overflow-hidden shadow-2xl flex flex-col group">
                      <div className="h-64 overflow-hidden relative">
                         <img src={route.thumbnail} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={route.title} />
                         <div className="absolute inset-0 bg-black/40 group-hover:bg-black/20 transition-all"></div>
                      </div>
                      <div className="p-10 flex-1">
                        <h3 className="text-3xl font-oswald font-black text-white uppercase italic tracking-tighter mb-4">{route.title}</h3>
                        <p className="text-zinc-500 text-sm leading-relaxed mb-8">{route.description}</p>
                        <button onClick={() => fetchInsights(route)} className="w-full bg-zinc-900 border border-zinc-800 text-yellow-500 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-yellow-500 hover:text-black transition-all">Briefing IA</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {currentView === 'gallery' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-blue-500 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Nossa <span className="text-yellow-500">Galeria</span></h2>
                </header>
                <div className="bg-zinc-900/30 p-20 rounded-[4rem] border border-zinc-900 text-center space-y-8 shadow-inner">
                   <ImageIcon size={64} className="text-yellow-500 mx-auto" />
                   <h3 className="text-4xl font-oswald font-black text-white uppercase italic">Registros no <span className="text-blue-500">Facebook</span></h3>
                   <a href="https://www.facebook.com/lamaaparecidabr/photos" target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-4 bg-yellow-500 text-black px-16 py-6 rounded-3xl font-black uppercase text-xs tracking-widest hover:bg-yellow-400 transition-all shadow-3xl">Ver Fotos Oficiais <ExternalLink size={20} /></a>
                </div>
              </div>
            )}

          </div>
        )}
      </main>

      {insights && insights !== 'carregando' && (
        <div className="fixed inset-0 z-[3000] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="bg-zinc-950 border border-zinc-900 p-16 rounded-[3rem] max-w-2xl w-full relative shadow-3xl">
            <button onClick={() => setInsights(null)} className="absolute top-8 right-8 text-zinc-600 hover:text-white font-black p-2">✕</button>
            <h3 className="text-3xl font-oswald font-black text-white uppercase italic mb-10">Briefing de <span className="text-yellow-500">Missão</span></h3>
            <div className="space-y-6">
              {insights.safetyTips.map((tip: string, i: number) => (
                <div key={i} className="p-6 bg-zinc-900/40 rounded-[1.5rem] border border-zinc-800/50 flex gap-4 text-zinc-300 shadow-sm">
                  <span className="text-yellow-500 font-black italic text-xl">0{i+1}</span>
                  <p className="font-light">{tip}</p>
                </div>
              ))}
              <div className="p-8 bg-yellow-500/5 rounded-[2.5rem] border border-yellow-500/10 italic text-zinc-400 text-center leading-relaxed">"{insights.scenicHighlight}"</div>
            </div>
          </div>
        </div>
      )}

      {insights === 'carregando' && (
        <div className="fixed inset-0 z-[3000] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-zinc-950 border border-zinc-900 p-10 rounded-[2rem] flex flex-col items-center gap-4 shadow-2xl">
            <Loader2 className="animate-spin text-yellow-500" size={40} />
            <p className="text-white font-oswald font-black uppercase italic tracking-widest">Consultando Gemini...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { RouteTracker } from './components/RouteTracker';
import { MapView } from './components/MapView';
import { View, User, Route } from './types';
import { Bike, Compass, Users, Calendar, Trophy, Image as ImageIcon, ExternalLink, Shield, Gauge, ChevronRight, Zap, Map, Volume2, VolumeX, Maximize2, MapPin, Navigation, Lock, Radio, Award, Star, Loader2, Edit2, Save, X, Camera, UserPlus, Key } from 'lucide-react';
import { getRouteInsights } from './services/geminiService';
import { supabase } from './services/supabaseClient';

const LAMA_LOGO_URL = 'https://github.com/lamaaparecidabr-lab/LAMA-APARECIDA/blob/main/components/logo.jpg?raw=true';
const YOUTUBE_ID = '-VzuMRXCizo';

const CLUBHOUSE_COORDS = { lat: -16.7908906, lng: -49.2311547 };
const CLUBHOUSE_ADDRESS = "R. X-011 - Sítios Santa Luzia, Aparecida de Goiânia - GO, 74922-570";
const CLUBHOUSE_MARK_NAME = "L.A.M.A. Aparecida Casa Club - Motorcycle Association";

const iconicRoutes: Route[] = [
  {
    id: 'iconic-1',
    title: 'Serra do Rio do Rastro (SC)',
    description: 'Uma das estradas mais desafiadoras e belas do mundo, com 284 curvas em 35km.',
    distance: '35 km',
    difficulty: 'Lendária',
    points: [],
    status: 'planejada',
    thumbnail: 'https://images.unsplash.com/photo-1469033092224-8a847a412338?q=80&w=800&auto=format&fit=crop',
    isOfficial: true
  },
  {
    id: 'iconic-2',
    title: 'Estrada Real (MG)',
    description: 'O caminho do ouro, cruzando cidades históricas e paisagens mineiras deslumbrantes.',
    distance: '500+ km',
    difficulty: 'Moderada',
    points: [],
    status: 'planejada',
    thumbnail: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=800&auto=format&fit=crop',
    isOfficial: true
  }
];

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [newMemberForm, setNewMemberForm] = useState({ email: '', password: '', name: '', bikeModel: '' });
  const [passwordForm, setPasswordForm] = useState({ newPassword: '', confirmPassword: '' });
  const [editForm, setEditForm] = useState({ name: '', bikeModel: '', avatar: '' });
  const [insights, setInsights] = useState<any>(null);
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    checkUser();

    // Escuta mudanças na autenticação em tempo real
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
    }
  }, [isAuthenticated]);

  const syncUserData = (supabaseUser: any) => {
    const userData: User = {
      id: supabaseUser.id,
      name: supabaseUser.user_metadata?.name || 'Membro L.A.M.A.',
      email: supabaseUser.email || '',
      bikeModel: supabaseUser.user_metadata?.bikeModel || 'Não informado',
      avatar: supabaseUser.user_metadata?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${supabaseUser.id}`,
      role: supabaseUser.user_metadata?.role || 'member'
    };
    setUser(userData);
    setEditForm({
      name: userData.name,
      bikeModel: userData.bikeModel || '',
      avatar: userData.avatar || ''
    });
    setIsAuthenticated(true);
  };

  const checkUser = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user) {
      syncUserData(session.user);
    }
    setIsLoading(false);
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      const mappedRoutes = data.map(r => ({
        ...r,
        isOfficial: r.is_official // Converte snake_case do DB para camelCase do App
      }));
      setRoutes(mappedRoutes);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { data, error } = await supabase.auth.signInWithPassword({
      email: loginForm.email,
      password: loginForm.password,
    });

    if (error) {
      alert("Erro no login: " + error.message);
      setIsLoading(false);
    }
    // O onAuthStateChange cuidará do resto
  };

  const handleRegisterNewMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    const { error } = await supabase.auth.signUp({
      email: newMemberForm.email,
      password: newMemberForm.password,
      options: {
        data: {
          name: newMemberForm.name,
          bikeModel: newMemberForm.bikeModel,
          role: 'member'
        }
      }
    });

    if (error) {
      alert("Erro ao cadastrar: " + error.message);
    } else {
      alert(`Membro ${newMemberForm.name} cadastrado com sucesso!`);
      // O Supabase Client desloga o admin ao criar novo user por padrão. 
      // Redirecionamos para home.
      handleLogout();
    }
    setIsUpdating(false);
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      data: {
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      }
    });

    if (error) {
      alert("Erro ao atualizar: " + error.message);
    } else {
      setIsEditingProfile(false);
      alert("Perfil atualizado com sucesso!");
      // O estado será atualizado pelo onAuthStateChange se necessário, 
      // ou podemos atualizar localmente:
      if (user) {
        setUser({ ...user, ...editForm });
      }
    }
    setIsUpdating(false);
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      alert("As senhas não coincidem!");
      return;
    }
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      password: passwordForm.newPassword
    });

    if (error) {
      alert("Erro ao trocar senha: " + error.message);
    } else {
      alert("Senha alterada com sucesso!");
      setIsChangingPassword(false);
      setPasswordForm({ newPassword: '', confirmPassword: '' });
    }
    setIsUpdating(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setView('home');
  };

  const handleSaveRoute = async (newRoute: Route) => {
    const { error } = await supabase
      .from('routes')
      .insert([{
        title: newRoute.title,
        description: newRoute.description,
        distance: newRoute.distance,
        difficulty: newRoute.difficulty,
        points: newRoute.points,
        status: newRoute.status,
        thumbnail: newRoute.thumbnail,
        is_official: newRoute.isOfficial, // Mapeia para snake_case do DB
        user_id: user?.id
      }]);

    if (error) {
      console.error("Erro ao salvar:", error);
      alert("Falha ao salvar rota no Mural.");
    } else {
      fetchRoutes();
    }
  };

  const fetchInsights = async (route: Route) => {
    setInsights('carregando');
    const result = await getRouteInsights(route.title, "Brasil");
    setInsights(result);
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: [] }), '*');
      setIsMuted(!isMuted);
    }
  };

  const publicViews = ['home', 'clubhouse'];
  const needsAuth = !isAuthenticated && !publicViews.includes(currentView);

  const renderLogin = () => (
    <div className="min-h-[70vh] flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-zinc-900/95 border border-zinc-800 p-12 rounded-[2.5rem] shadow-2xl backdrop-blur-xl">
        <div className="text-center mb-10">
          <img src={LAMA_LOGO_URL} alt="Logo" className="w-24 h-24 mx-auto mb-6" />
          <h2 className="text-3xl font-oswald text-white font-black uppercase italic tracking-tighter">Sede Virtual</h2>
          <p className="text-zinc-500 text-[10px] mt-2 uppercase tracking-widest font-black">Acesso Exclusivo para Membros</p>
        </div>
        <form onSubmit={handleLogin} className="space-y-4">
          <input
            type="email"
            required
            className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none placeholder:text-zinc-800 focus:border-yellow-500/50 transition-all"
            placeholder="membro@lama.com"
            value={loginForm.email}
            onChange={e => setLoginForm({...loginForm, email: e.target.value})}
          />
          <input
            type="password"
            required
            className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none placeholder:text-zinc-800 focus:border-yellow-500/50 transition-all"
            placeholder="Senha de Acesso"
            value={loginForm.password}
            onChange={e => setLoginForm({...loginForm, password: e.target.value})}
          />
          <button type="submit" disabled={isLoading} className="w-full bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3">
            {isLoading ? <Loader2 className="animate-spin" size={16} /> : <>Entrar na Sede <Zap size={16} /></>}
          </button>
        </form>
      </div>
    </div>
  );

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-6">
        <Loader2 className="text-yellow-500 animate-spin" size={48} />
        <p className="text-yellow-500 font-oswald font-bold uppercase tracking-widest animate-pulse italic">Validando Missão...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#050505] text-zinc-300">
      <Sidebar user={user} currentView={currentView} setView={setView} onLogout={handleLogout} />

      <main className="flex-1 p-5 md:p-12 pb-24 md:pb-12 max-w-[1400px] mx-auto w-full overflow-y-auto custom-scrollbar">
        {needsAuth ? renderLogin() : (
          <div className="animate-in fade-in duration-700">

            {currentView === 'home' && (
              <div className="space-y-12">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-zinc-900 pb-16">
                  <div className="flex items-center gap-10">
                    <img src={LAMA_LOGO_URL} alt="Logo" className="w-28 h-28 object-contain" />
                    <div>
                      <span className="text-yellow-500 font-black uppercase tracking-widest text-lg">LATIN AMERICAN MOTORCYCLE ASSOCIATION</span>
                      <h1 className="text-5xl font-oswald font-black text-white uppercase italic mt-2">Capítulo <span className="text-yellow-500">Aparecida</span></h1>
                    </div>
                  </div>
                </header>
