                        <button onClick={() => fetchInsights(route)} className="w-full bg-zinc-900 border border-zinc-800 text-yellow-500 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-yellow-500 hover:text-black transition-all">Briefing IA</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {currentView === 'gallery' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-blue-500 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Nossa <span className="text-yellow-500">Galeria</span></h2>
                </header>
                <div className="bg-zinc-900/30 p-20 rounded-[4rem] border border-zinc-900 text-center space-y-8 shadow-inner">
                   <ImageIcon size={64} className="text-yellow-500 mx-auto" />
                   <h3 className="text-4xl font-oswald font-black text-white uppercase italic">Registros no <span className="text-blue-500">Facebook</span></h3>
                   <a href="https://www.facebook.com/lamaaparecidabr/photos" target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-4 bg-yellow-500 text-black px-16 py-6 rounded-3xl font-black uppercase text-xs tracking-widest hover:bg-yellow-400 transition-all shadow-3xl">Ver Fotos Oficiais <ExternalLink size={20} /></a>
                </div>
              </div>
            )}

          </div>
        )}
      </main>

      {insights && insights !== 'carregando' && (
        <div className="fixed inset-0 z-[3000] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="bg-zinc-950 border border-zinc-900 p-16 rounded-[3rem] max-w-2xl w-full relative shadow-3xl">
            <button onClick={() => setInsights(null)} className="absolute top-8 right-8 text-zinc-600 hover:text-white font-black p-2 transition-colors">✕</button>
            <h3 className="text-3xl font-oswald font-black text-white uppercase italic mb-10">Briefing de <span className="text-yellow-500">Missão</span></h3>
            <div className="space-y-6">
              {insights.safetyTips.map((tip: string, i: number) => (
                <div key={i} className="p-6 bg-zinc-900/40 rounded-[1.5rem] border border-zinc-800/50 flex gap-4 text-zinc-300 shadow-sm">
                  <span className="text-yellow-500 font-black italic text-xl">0{i+1}</span>
                  <p className="font-light">{tip}</p>
                </div>
              ))}
              <div className="p-8 bg-yellow-500/5 rounded-[2.5rem] border border-yellow-500/10 italic text-zinc-400 text-center leading-relaxed">"{insights.scenicHighlight}"</div>
            </div>
          </div>
        </div>
      )}

      {insights === 'carregando' && (
        <div className="fixed inset-0 z-[3000] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-zinc-950 border border-zinc-900 p-10 rounded-[2rem] flex flex-col items-center gap-4 shadow-2xl">
            <Loader2 className="animate-spin text-yellow-500" size={40} />
            <p className="text-white font-oswald font-black uppercase italic tracking-widest">Consultando Gemini...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { Home, Compass, Map, User, LogOut, Radio, Image as ImageIcon, MapPin, Settings } from 'lucide-react';
import { View, User as UserType } from '../types';

interface SidebarProps {
  user: UserType | null;
  currentView: View;
  setView: (view: View) => void;
  onLogout: () => void;
}

const LAMA_LOGO_URL = 'https://github.com/lamaaparecidabr-lab/LAMA-APARECIDA/blob/main/components/logo.jpg?raw=true';

export const Sidebar: React.FC<SidebarProps> = ({ user, currentView, setView, onLogout }) => {
  const isAdmin = user?.role === 'admin';

  const menuItems = [
    { id: 'home', icon: Home, label: 'Início' },
    { id: 'clubhouse', icon: MapPin, label: 'Sede' },
    { id: 'explorer', icon: Compass, label: 'Icônicas' },
    { id: 'tracking', icon: Radio, label: 'Gravar' },
    { id: 'my-routes', icon: Map, label: 'Mural' },
    { id: 'gallery', icon: ImageIcon, label: 'Galeria' },
    { id: 'profile', icon: User, label: 'Perfil' },
  ];

  if (isAdmin) {
    menuItems.push({ id: 'admin', icon: Settings, label: 'Admin' });
  }

  return (
    <>
      {/* Desktop Sidebar */}
      <aside className="hidden md:flex w-80 bg-black border-r border-zinc-900 flex-col h-screen sticky top-0 z-40 shadow-2xl">
        <div className="p-10 flex flex-row items-center gap-6">
          <div className="relative group shrink-0">
            <div className="absolute inset-0 bg-yellow-500/20 blur-3xl rounded-full scale-150 opacity-0 group-hover:opacity-100 transition-all duration-700"></div>
            <img src={LAMA_LOGO_URL} alt="LAMA" className="relative w-16 h-16 object-contain filter drop-shadow-[0_0_15px_rgba(234,179,8,0.4)] transform group-hover:scale-110 transition-transform duration-500" />
          </div>
          <div className="relative">
            <div className="flex flex-col">
              <h1 className="font-oswald text-3xl font-black tracking-[0.10em] uppercase italic leading-[0.75] text-white">
                L.A.M.A.
              </h1>
              <div className="flex items-center gap-2 mt-1">
                <span className="text-yellow-500 font-black uppercase tracking-[0.2em] text-[15px] font-oswald italic">Aparecida</span>
              </div>
            </div>
          </div>
        </div>

        <nav className="flex-1 px-6 py-8 overflow-y-auto custom-scrollbar">
          <ul className="space-y-3">
            {menuItems.map((item) => (
              <li key={item.id}>
                <button
                  onClick={() => setView(item.id as View)}
                  className={`w-full flex items-center gap-6 px-7 py-4 rounded-[2rem] transition-all relative group overflow-hidden ${
                    currentView === item.id
                      ? 'bg-zinc-900/50 text-yellow-500 border border-yellow-500/20 shadow-[0_10px_30px_-10px_rgba(234,179,8,0.2)]'
                      : 'text-zinc-700 hover:bg-zinc-900/20 hover:text-zinc-400'
                  }`}
                >
                  {currentView === item.id && (
                    <div className="absolute left-0 w-2 h-8 bg-yellow-500 rounded-r-full shadow-[0_0_20px_rgba(234,179,8,0.6)]"></div>
                  )}
                  <item.icon size={20} className={currentView === item.id ? 'scale-110' : ''} />
                  <span className="font-black uppercase tracking-[0.25em] text-[9px] italic leading-none">{item.label}</span>
                </button>
              </li>
            ))}
          </ul>
        </nav>

        {user && (
          <div className="p-8 border-t border-zinc-900/50">
            <button 
              onClick={onLogout} 
              className="w-full flex items-center gap-6 px-7 py-5 text-zinc-800 hover:text-red-600 hover:bg-red-600/5 rounded-[2rem] transition-all group"
            >
              <LogOut size={22} className="group-hover:-translate-x-1 transition-transform" />
              <span className="font-black uppercase tracking-[0.25em] text-[9px]">Sair do Radar</span>
            </button>
          </div>
        )}
      </aside>

      {/* Mobile Bottom Navigation */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-black/95 backdrop-blur-xl border-t border-zinc-900 p-1 z-[2000] shadow-[0_-5px_30px_rgba(0,0,0,0.8)]">
        <div className="grid grid-cols-5 gap-0">
          {menuItems.slice(0, 4).map((item) => (
            <button
              key={item.id}
              onClick={() => setView(item.id as View)}
              className={`flex flex-col items-center justify-center py-2 rounded-lg ${
                currentView === item.id ? 'text-yellow-500' : 'text-zinc-500'
              }`}
            >
              <item.icon size={16} />
              <span className="text-[6px] font-black uppercase mt-1">{item.label}</span>
            </button>
          ))}
          <button
            onClick={() => setView('profile')}
            className={`flex flex-col items-center justify-center py-2 rounded-lg ${
              currentView === 'profile' ? 'text-yellow-500' : 'text-zinc-500'
            }`}
          >
            <User size={16} />
            <span className="text-[6px] font-black uppercase mt-1">Perfil</span>
          </button>
        </div>
      </nav>
    </>
  );
};

export interface User {
  id: string;
  name: string;
  email: string;
  bikeModel?: string;
  avatar?: string;
  role?: 'admin' | 'member';
}

export interface RoutePoint {
  lat: number;
  lng: number;
  timestamp: number;
}

export interface Route {
  id: string;
  user_id?: string;
  title: string;
  description: string;
  distance: string;
  difficulty: 'Fácil' | 'Moderada' | 'Difícil' | 'Lendária';
  points: RoutePoint[];
  status: 'planejada' | 'concluída' | 'ativa';
  thumbnail?: string;
  isOfficial?: boolean;
}

export type View = 'home' | 'explorer' | 'my-routes' | 'profile' | 'tracking' | 'gallery' | 'clubhouse' | 'admin';

import React, { useState, useEffect, useRef } from 'react';
import { Sidebar } from './components/Sidebar';
import { RouteTracker } from './components/RouteTracker';
import { MapView } from './components/MapView';
import { View, User, Route } from './types';
import { Bike, Compass, Users, Calendar, Trophy, Image as ImageIcon, ExternalLink, Shield, Gauge, ChevronRight, Zap, Map, Volume2, VolumeX, Maximize2, MapPin, Navigation, Lock, Radio, Award, Star, Loader2, Edit2, Save, X, Camera, UserPlus, Key, Trash2 } from 'lucide-react';
import { getRouteInsights } from './services/geminiService';
import { supabase } from './services/supabaseClient';

const LAMA_LOGO_URL = 'https://github.com/lamaaparecidabr-lab/LAMA-APARECIDA/blob/main/components/logo.jpg?raw=true';
const YOUTUBE_ID = '-VzuMRXCizo';

const CLUBHOUSE_COORDS = { lat: -16.7908906, lng: -49.2311547 };
const CLUBHOUSE_ADDRESS = "R. X-011 - Sítios Santa Luzia, Aparecida de Goiânia - GO, 74922-570";
const CLUBHOUSE_MARK_NAME = "L.A.M.A. Aparecida Casa Club - Motorcycle Association";

const iconicRoutes: Route[] = [
  {
    id: 'iconic-1',
    title: 'Serra do Rio do Rastro (SC)',
    description: 'Uma das estradas mais desafiadoras e belas do mundo, com 284 curvas em 35km.',
    distance: '35 km',
    difficulty: 'Lendária',
    points: [],
    status: 'planejada',
    thumbnail: 'https://images.unsplash.com/photo-1469033092224-8a847a412338?q=80&w=800&auto=format&fit=crop',
    isOfficial: true
  },
  {
    id: 'iconic-2',
    title: 'Estrada Real (MG)',
    description: 'O caminho do ouro, cruzando cidades históricas e paisagens mineiras deslumbrantes.',
    distance: '500+ km',
    difficulty: 'Moderada',
    points: [],
    status: 'planejada',
    thumbnail: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=800&auto=format&fit=crop',
    isOfficial: true
  }
];

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [newMemberForm, setNewMemberForm] = useState({ email: '', password: '', name: '', bikeModel: '' });
  const [passwordForm, setPasswordForm] = useState({ newPassword: '', confirmPassword: '' });
  const [editForm, setEditForm] = useState({ name: '', bikeModel: '', avatar: '' });
  const [insights, setInsights] = useState<any>(null);
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    checkUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
    }
  }, [isAuthenticated]);

  const syncUserData = (supabaseUser: any) => {
    const userData: User = {
      id: supabaseUser.id,
      name: supabaseUser.user_metadata?.name || 'Membro L.A.M.A.',
      email: supabaseUser.email || '',
      bikeModel: supabaseUser.user_metadata?.bikeModel || 'Não informado',
      avatar: supabaseUser.user_metadata?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${supabaseUser.id}`,
      role: supabaseUser.user_metadata?.role || 'member'
    };
    setUser(userData);
    setEditForm({
      name: userData.name,
      bikeModel: userData.bikeModel || '',
      avatar: userData.avatar || ''
    });
    setIsAuthenticated(true);
  };

  const checkUser = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user) {
      syncUserData(session.user);
    }
    setIsLoading(false);
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      const mappedRoutes = data.map(r => ({
        ...r,
        isOfficial: r.is_official
      }));
      setRoutes(mappedRoutes);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { error } = await supabase.auth.signInWithPassword({
      email: loginForm.email,
      password: loginForm.password,
    });

    if (error) {
      alert("Erro no login: " + error.message);
      setIsLoading(false);
    }
  };

  const handleRegisterNewMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    const { error } = await supabase.auth.signUp({
      email: newMemberForm.email,
      password: newMemberForm.password,
      options: {
        data: {
          name: newMemberForm.name,
          bikeModel: newMemberForm.bikeModel,
          role: 'member'
        }
      }
    });

    if (error) {
      alert("Erro ao cadastrar: " + error.message);
    } else {
      alert(`Membro ${newMemberForm.name} cadastrado com sucesso!`);
      handleLogout();
    }
    setIsUpdating(false);
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      data: {
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      }
    });

    if (error) {
      alert("Erro ao atualizar: " + error.message);
    } else {
      setIsEditingProfile(false);
      alert("Perfil atualizado com sucesso!");
      if (user) {
        setUser({ ...user, ...editForm });
      }
    }
    setIsUpdating(false);
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      alert("As senhas não coincidem!");
      return;
    }
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      password: passwordForm.newPassword
    });

    if (error) {
      alert("Erro ao trocar senha: " + error.message);
    } else {
      alert("Senha alterada com sucesso!");
      setIsChangingPassword(false);
      setPasswordForm({ newPassword: '', confirmPassword: '' });
    }
    setIsUpdating(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setView('home');
  };

  const handleSaveRoute = async (newRoute: Route) => {
    const { error } = await supabase
      .from('routes')
      .insert([{
        title: newRoute.title,
        description: newRoute.description,
        distance: newRoute.distance,
        difficulty: newRoute.difficulty,
        points: newRoute.points,
        status: newRoute.status,
        thumbnail: newRoute.thumbnail,
        is_official: newRoute.isOfficial,
        user_id: user?.id
      }]);

    if (error) {
      alert("Falha ao salvar rota no Mural.");
    } else {
      fetchRoutes();
    }
  };

  const handleDeleteRoute = async (routeId: string) => {
    if (!confirm("Deseja realmente apagar este registro de missão?")) return;

    const { error } = await supabase
      .from('routes')
      .delete()
      .eq('id', routeId);

    if (error) {
      alert("Erro ao excluir: " + error.message);
    } else {
      setRoutes(routes.filter(r => r.id !== routeId));
    }
  };

  const fetchInsights = async (route: Route) => {
    setInsights('carregando');
    const result = await getRouteInsights(route.title, "Brasil");
    setInsights(result);
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: [] }), '*');
      setIsMuted(!isMuted);
    }
  };

  const publicViews = ['home', 'clubhouse'];
  const needsAuth = !isAuthenticated && !publicViews.includes(currentView);

  const renderLogin = () => (
    <div className="min-h-[70vh] flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-zinc-900/95 border border-zinc-800 p-12 rounded-[2.5rem] shadow-2xl backdrop-blur-xl">
        <div className="text-center mb-10">
          <img src={LAMA_LOGO_URL} alt="Logo" className="w-24 h-24 mx-auto mb-6" />
          <h2 className="text-3xl font-oswald text-white font-black uppercase italic tracking-tighter">Sede Virtual</h2>
          <p className="text-zinc-500 text-[10px] mt-2 uppercase tracking-widest font-black">Acesso Exclusivo para Membros</p>
        </div>
        <form onSubmit={handleLogin} className="space-y-4">
          <input
            type="email"
            required
            className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none placeholder:text-zinc-800 focus:border-yellow-500/50 transition-all"
            placeholder="membro@lama.com"
            value={loginForm.email}
            onChange={e => setLoginForm({...loginForm, email: e.target.value})}
          />
          <input
            type="password"
            required
            className="w-full bg-black/50 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none placeholder:text-zinc-800 focus:border-yellow-500/50 transition-all"
            placeholder="Senha de Acesso"
            value={loginForm.password}
            onChange={e => setLoginForm({...loginForm, password: e.target.value})}
          />
          <button type="submit" disabled={isLoading} className="w-full bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3">
            {isLoading ? <Loader2 className="animate-spin" size={16} /> : <>Entrar na Sede <Zap size={16} /></>}
          </button>
        </form>
      </div>
    </div>
  );

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-6">
        <Loader2 className="text-yellow-500 animate-spin" size={48} />
        <p className="text-yellow-500 font-oswald font-bold uppercase tracking-widest animate-pulse italic">Validando Missão...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#050505] text-zinc-300">
      <Sidebar user={user} currentView={currentView} setView={setView} onLogout={handleLogout} />

      <main className="flex-1 p-5 md:p-12 pb-24 md:pb-12 max-w-[1400px] mx-auto w-full overflow-y-auto custom-scrollbar">
        {needsAuth ? renderLogin() : (
          <div className="animate-in fade-in duration-700">

            {currentView === 'home' && (
              <div className="space-y-12">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-zinc-900 pb-16">
                  <div className="flex items-center gap-10">
                    <img src={LAMA_LOGO_URL} alt="Logo" className="w-28 h-28 object-contain" />
                    <div>
                      <span className="text-yellow-500 font-black uppercase tracking-widest text-lg">LATIN AMERICAN MOTORCYCLE ASSOCIATION</span>
                      <h1 className="text-5xl font-oswald font-black text-white uppercase italic mt-2">Capítulo <span className="text-yellow-500">Aparecida</span></h1>
                    </div>
                  </div>
                </header>
                <section className="relative rounded-[4rem] overflow-hidden bg-zinc-900 border border-zinc-800 aspect-[21/9] shadow-3xl group">
                  <iframe 
                    ref={videoRef}
                    className="w-full h-full object-cover opacity-60"
                    src={`https://www.youtube.com/embed/${YOUTUBE_ID}?autoplay=1&mute=1&loop=1&playlist=${YOUTUBE_ID}&controls=0&enablejsapi=1`} 
                    frameBorder="0"
                  ></iframe>
                  <div className="absolute inset-0 z-20 p-16 flex flex-col justify-end">
                    <h3 className="text-7xl font-oswald font-black text-white uppercase italic mb-8 leading-none">Respeito <span className="text-yellow-500">& Liberdade.</span></h3>
                    <div className="flex gap-4">
                       <button onClick={() => setView('clubhouse')} className="bg-white text-black px-12 py-5 rounded-[1.8rem] font-black uppercase text-[11px] hover:bg-yellow-500 transition-all shadow-xl">Visitar Sede</button>
                       <button onClick={toggleMute} className="bg-zinc-900/80 backdrop-blur-md text-white p-5 rounded-[1.5rem] hover:bg-yellow-500 hover:text-black transition-all shadow-xl">{isMuted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
                    </div>
                  </div>
                </section>
              </div>
            )}

            {currentView === 'admin' && user?.role === 'admin' && (
              <div className="max-w-4xl mx-auto space-y-12">
                <header className="flex items-center gap-4">
                  <div className="w-2 h-10 bg-yellow-500 rounded-full"></div>
                  <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Administração do <span className="text-yellow-500">Capítulo</span></h2>
                </header>
                <div className="bg-zinc-950 p-12 rounded-[3rem] border border-zinc-900 shadow-3xl">
                  <h3 className="text-2xl font-oswald font-black text-white uppercase mb-8 flex items-center gap-3"><UserPlus size={24} className="text-yellow-500" /> Cadastrar Novo Membro</h3>
                  <form onSubmit={handleRegisterNewMember} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Nome de Estrada</label>
                      <input type="text" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" placeholder="Ex: Relâmpago" value={newMemberForm.name} onChange={e => setNewMemberForm({...newMemberForm, name: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Email Oficial</label>
                      <input type="email" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" placeholder="membro@lama.com" value={newMemberForm.email} onChange={e => setNewMemberForm({...newMemberForm, email: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Motocicleta</label>
                      <input type="text" className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" placeholder="Harley-Davidson Fat Boy" value={newMemberForm.bikeModel} onChange={e => setNewMemberForm({...newMemberForm, bikeModel: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Senha Provisória</label>
                      <input type="text" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" placeholder="mudar123" value={newMemberForm.password} onChange={e => setNewMemberForm({...newMemberForm, password: e.target.value})} />
                    </div>
                    <button type="submit" disabled={isUpdating} className="md:col-span-2 bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl active:scale-95 flex items-center justify-center gap-3">
                      {isUpdating ? <Loader2 className="animate-spin" size={16} /> : <><Save size={16} /> Confirmar Cadastro</>}
                    </button>
                  </form>
                </div>
              </div>
            )}

            {currentView === 'profile' && (
              <div className="max-w-5xl mx-auto space-y-10">
                <header className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-2 h-10 bg-yellow-500 rounded-full"></div>
                    <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Área do <span className="text-yellow-500">Membro</span></h2>
                  </div>
                  <div className="flex gap-4">
                    <button onClick={() => setIsChangingPassword(!isChangingPassword)} className="flex items-center gap-2 px-6 py-3 bg-zinc-900 border border-zinc-800 rounded-xl hover:bg-red-600 hover:text-white transition-all text-[10px] font-black uppercase tracking-widest">
                      <Key size={14} /> Alterar Senha
                    </button>
                    <button onClick={() => setIsEditingProfile(!isEditingProfile)} className="flex items-center gap-2 px-6 py-3 bg-zinc-900 border border-zinc-800 rounded-xl hover:bg-yellow-500 hover:text-black transition-all text-[10px] font-black uppercase tracking-widest">
                      <Edit2 size={14} /> Editar Perfil
                    </button>
                  </div>
                </header>

                <div className="relative bg-zinc-950 p-16 rounded-[3rem] border border-zinc-900 shadow-3xl overflow-hidden">
                  {isEditingProfile ? (
                    <form onSubmit={handleUpdateProfile} className="space-y-8">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-2">
                          <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Nome de Estrada</label>
                          <input type="text" required className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" value={editForm.name} onChange={e => setEditForm({...editForm, name: e.target.value})} />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">Máquina Principal</label>
                          <input type="text" className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" value={editForm.bikeModel} onChange={e => setEditForm({...editForm, bikeModel: e.target.value})} />
                        </div>
                        <div className="md:col-span-2 space-y-2">
                          <label className="text-[9px] font-black uppercase tracking-widest text-zinc-600 ml-4">URL da Foto de Perfil (Avatar)</label>
                          <input type="url" className="w-full bg-zinc-900 border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none" placeholder="https://imagem.com/foto.jpg" value={editForm.avatar} onChange={e => setEditForm({...editForm, avatar: e.target.value})} />
                        </div>
                      </div>
                      <div className="flex justify-end gap-4">
                        <button type="button" onClick={() => setIsEditingProfile(false)} className="px-8 py-4 text-zinc-500 font-black uppercase text-[10px] hover:text-white transition-all">Cancelar</button>
                        <button type="submit" disabled={isUpdating} className="bg-yellow-500 text-black px-12 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-yellow-400 transition-all">
                          {isUpdating ? <Loader2 className="animate-spin" size={14} /> : "Salvar Perfil"}
                        </button>
                      </div>
                    </form>
                  ) : (
                    <div className="flex flex-col md:flex-row items-center md:items-start gap-16">
                      <div className="relative shrink-0">
                         <div className="absolute inset-0 bg-yellow-500/10 blur-3xl rounded-full"></div>
                         <img src={user?.avatar} alt="Avatar" className="relative w-64 h-64 rounded-[2.5rem] border-4 border-zinc-950 object-cover shadow-2xl" />
                         {user?.role === 'admin' && (
                           <div className="absolute -top-4 -right-4 bg-yellow-500 text-black px-4 py-2 rounded-xl font-black text-[10px] uppercase italic shadow-xl z-30">
                             SUPERUSER
                           </div>
                         )}
                      </div>
                      <div className="flex-1 space-y-8 text-center md:text-left">
                        <div>
                          <span className="inline-block px-3 py-1 bg-yellow-500/10 text-yellow-500 text-[10px] font-black uppercase rounded-lg mb-4">
                            {user?.role === 'admin' ? 'Administrador L.A.M.A.' : 'Membro Capítulo Aparecida'}
                          </span>
                          <h2 className="text-7xl font-oswald font-black text-white uppercase italic tracking-tighter leading-none mb-4">LAMA: <span className="text-yellow-500">{user?.name}</span></h2>
                          <p className="text-zinc-500 font-black uppercase tracking-widest text-xs italic">{user?.email}</p>
                        </div>
                        <div className="bg-zinc-900/40 p-8 rounded-[2rem] border border-zinc-900/50 inline-flex items-center gap-6 shadow-lg">
                           <div className="p-4 bg-yellow-500/10 rounded-2xl"><Bike size={28} className="text-yellow-500" /></div>
                           <div className="text-left">
                              <span className="text-[9px] text-zinc-600 font-black uppercase tracking-widest">Máquina de Estrada</span>
                              <p className="font-bold text-white text-xl tracking-tight uppercase italic">{user?.bikeModel}</p>
                           </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            {currentView === 'tracking' && <RouteTracker onSave={handleSaveRoute} />}

            {currentView === 'my-routes' && (
              <div className="space-y-12">
                <header className="flex items-center gap-4">
                   <div className="w-2 h-10 bg-red-600 rounded-full"></div>
                   <h2 className="text-4xl font-oswald font-black text-white italic uppercase tracking-tighter">Mural de <span className="text-yellow-500">Missões</span></h2>
                </header>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                  {routes.length > 0 ? routes.map(route => (
                    <div key={route.id} className="bg-zinc-950 rounded-[2.5rem] border border-zinc-900 overflow-hidden shadow-2xl group hover:border-yellow-500/30 transition-all flex flex-col relative">
                      <MapView points={route.points} className="h-48 border-none rounded-none grayscale group-hover:grayscale-0 transition-all" />

                      {(route.user_id === user?.id || user?.role === 'admin') && (
                        <button 
                          onClick={() => handleDeleteRoute(route.id)}
                          className="absolute top-4 right-4 p-3 bg-black/60 backdrop-blur-md rounded-xl text-zinc-500 hover:text-red-500 transition-all opacity-0 group-hover:opacity-100 z-10"
                        >
                          <Trash2 size={16} />
                        </button>
                      )}

                      <div className="p-8">
                        <div className="flex justify-between items-start mb-2">
                           <h3 className="text-2xl font-oswald font-black text-white uppercase italic tracking-tighter truncate max-w-[70%]">{route.title}</h3>
                           {route.isOfficial && <span className="bg-yellow-500 text-black text-[8px] px-2 py-0.5 rounded font-black uppercase italic">Oficial</span>}
                        </div>
                        <div className="flex items-center justify-between mt-4">
                           <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest">{route.distance} Rodados</p>
                           <span className="text-yellow-500 font-black text-[9px] uppercase italic">{route.difficulty}</span>
                        </div>
                      </div>
                    </div>
                  )) : (
                    <div className="col-span-full py-32 text-center bg-zinc-900/10 rounded-[3rem] border border-dashed border-zinc-800 text-zinc-500 font-black uppercase italic tracking-widest">Aguardando telemetria na base de dados...</div>
                  )}
                </div>
              </div>
            )}

            {currentView === 'clubhouse' && (
              <div className="space-y-12">
                <header className="flex items-center gap-6">
                   <div className="w-3 h-14 bg-yellow-500 rounded-full"></div>
