        .from('profiles')
        .select('role, name, bike_model, avatar_url, birth_date')
        .eq('id', supabaseUser.id)
        .single();

      if (error && retryCount < 3) {
        setTimeout(() => syncUserData(supabaseUser, retryCount + 1), 500);
        return;
      }

      const userData: User = {
        id: supabaseUser.id,
        name: profile?.name || supabaseUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: supabaseUser.email || '',
        bikeModel: profile?.bike_model || supabaseUser.user_metadata?.bikeModel || 'Não informado',
        avatar: profile?.avatar_url || supabaseUser.user_metadata?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${supabaseUser.id}`,
        birthDate: profile?.birth_date || '',
        role: (profile?.role as 'admin' | 'member') || (supabaseUser.email === SUPERUSER_EMAIL ? 'admin' : 'member')
      };

      setUser(userData);
      setEditForm({
        name: userData.name,
        bikeModel: userData.bikeModel || '',
        avatar: userData.avatar || '',
        birthDate: userData.birthDate || ''
      });
      setIsAuthenticated(true);
    } catch (err) {
      console.error("Erro na sincronização de dados:", err);
      setIsAuthenticated(true);
    }
  };

  const checkUser = async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        await syncUserData(session.user);
      }
    } catch (e) {
      console.error("Erro ao verificar sessão inicial:", e);
    } finally {
      setIsLoading(false);
    }
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      const mappedRoutes = data.map(r => ({
        ...r,
        isOfficial: r.is_official
      }));
      setRoutes(mappedRoutes);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { error } = await supabase.auth.signInWithPassword({
      email: loginForm.email.trim(),
      password: loginForm.password,
    });

    if (error) {
      alert("Radar falhou: " + error.message);
      setIsLoading(false);
    }
  };

  const handleRegisterNewMember = async (e: React.FormEvent) => {
    e.preventDefault();
    if (user?.role !== 'admin') {
      alert("Acesso Negado: Apenas o Capitão pode recrutar novos membros.");
      return;
    }
    setIsUpdating(true);
    const { error } = await supabase.auth.signUp({
      email: newMemberForm.email.trim(),
      password: newMemberForm.password,
      options: {
        data: {
          name: newMemberForm.name,
          bikeModel: newMemberForm.bikeModel,
          role: 'member'
        }
      }
    });

    if (error) {
      alert("Erro no recrutamento: " + error.message);
    } else {
      alert(`Novo membro ${newMemberForm.name} recrutado com sucesso!`);
      setNewMemberForm({ email: '', password: '', name: '', bikeModel: '' });
    }
    setIsUpdating(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert("Erro: Por favor, selecione um arquivo de imagem válido (JPG ou PNG).");
        return;
      }
      if (file.size > 2 * 1024 * 1024) {
        alert("Arquivo muito pesado! O limite é de 2MB por foto.");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setIsUpdating(true);

    const { error: authError } = await supabase.auth.updateUser({
      data: {
        name: editForm.name,
        bikeModel: editForm.bikeModel,
        avatar: editForm.avatar
      }
    });

    const { error: dbError } = await supabase
      .from('profiles')
      .update({
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate
      })
      .eq('id', user.id);

    if (authError || dbError) {
      console.error(authError, dbError);
      alert("Falha na telemetria de perfil.");
    } else {
      setIsEditingProfile(false);
      alert("Perfil atualizado!");
      setUser({ ...user, ...editForm });
    }
    setIsUpdating(false);
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordForm.newPassword.length < 6) {
      alert("Senha deve ter no mínimo 6 caracteres.");
      return;
    }
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      alert("As senhas não batem!");
      return;
    }
    setIsUpdating(true);
    const { error } = await supabase.auth.updateUser({
      password: passwordForm.newPassword
    });

    if (error) {
      alert("Erro ao redefinir: " + error.message);
    } else {
      alert("Senha alterada!");
      setIsChangingPassword(false);
      setPasswordForm({ newPassword: '', confirmPassword: '' });
    }
    setIsUpdating(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setView('home');
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (newRoute.points.length > 5000) {
      alert("Erro: Rota muito longa.");
      return;
    }

    const { error } = await supabase
      .from('routes')
      .insert([{
        title: newRoute.title.substring(0, 100),
        description: newRoute.description.substring(0, 500),
        distance: newRoute.distance,
        difficulty: newRoute.difficulty,
        points: newRoute.points,
        status: newRoute.status,
        thumbnail: newRoute.thumbnail,
        is_official: user?.role === 'admin',
        user_id: user?.id
      }]);

    if (error) {
      console.error(error);
      alert("Falha ao transmitir rota. Verifique as permissões.");
    } else {
      fetchRoutes();
      alert("Missão enviada para o Mural!");
    }
  };

  const handleDeleteRoute = async (routeId: string) => {
    if (!confirm("Deseja realmente apagar este registro?")) return;

    const { error } = await supabase
      .from('routes')
      .delete()
      .eq('id', routeId);

    if (error) {
      alert("Erro ao excluir: " + error.message);
