             <Loader2 className="animate-spin text-yellow-500" size={48} />
             <p className="text-white font-oswald font-black uppercase italic tracking-widest text-sm">Consultando Radar Gemini...</p>
          </div>
        </div>
      )}
    </div>
  );
};

