Sim, você **precisa** rodar um script SQL no painel do Supabase para que as tabelas de perfis e rotas funcionem com as permissões corretas. O erro "Failed to fetch" no Vercel é causado por tentar salvar uma imagem grande nos metadados de autenticação do Supabase (que são passados via headers HTTP e têm um limite rigoroso).

Eu corrigi o código do seu aplicativo para salvar a imagem pesada apenas na tabela `profiles` do banco de dados e usei o comando `upsert`, o que garante que o salvamento funcione mesmo se o perfil ainda não existir.

### Siga estes passos para configurar o Supabase:

1. Acesse o painel do seu projeto no **Supabase**.
2. Clique em **SQL Editor** no menu lateral esquerdo (ícone `>_`).
3. Clique em **New Query**.
4. Cole o código abaixo e clique em **Run**:

```sql
-- 1. Criar tabela de Perfis
create table if not exists public.profiles (
  id uuid references auth.users on delete cascade not null primary key,
  updated_at timestamp with time zone default now(),
  name text,
  bike_model text,
  avatar_url text,
  birth_date date,
  role text default 'member'
);

-- 2. Criar tabela de Rotas
create table if not exists public.routes (
  id uuid default gen_random_uuid() primary key,
  created_at timestamp with time zone default now() not null,
  user_id uuid references auth.users on delete cascade,
  title text,
  description text,
  distance text,
  difficulty text,
  points jsonb,
  status text,
  thumbnail text,
  is_official boolean default false
);

-- 3. Habilitar Segurança (RLS)
alter table public.profiles enable row level security;
alter table public.routes enable row level security;

-- 4. Políticas para Perfis
create policy "Perfis são públicos para leitura." on public.profiles for select using (true);
create policy "Usuários atualizam próprio perfil." on public.profiles for update using (auth.uid() = id);
create policy "Usuários inserem próprio perfil." on public.profiles for insert with check (auth.uid() = id);

-- 5. Políticas para Rotas
create policy "Rotas são públicas para leitura." on public.routes for select using (true);
create policy "Usuários inserem próprias rotas." on public.routes for insert with check (auth.uid() = user_id);
create policy "Usuários apagam próprias rotas." on public.routes for delete using (auth.uid() = user_id);

-- 6. Trigger para criar perfil automaticamente no cadastro
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, name, bike_model, role)
  values (new.id, new.raw_user_meta_data->>'name', new.raw_user_meta_data->>'bikeModel', coalesce(new.raw_user_meta_data->>'role', 'member'));
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();
```

