    try {
      const { error } = await supabase.from('routes').insert([{
        ...newRoute,
        user_id: user.id
      }]);
      if (error) throw error;
      await fetchRoutes();
    } catch (error) {
      console.error("Error saving route:", error);
      setRoutes(prev => [newRoute, ...prev]);
    }
