                  <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent"></div>
                  <div className="absolute bottom-12 left-12 right-12">
                     <h2 className="text-5xl md:text-8xl font-oswald font-black uppercase italic tracking-tighter leading-none mb-4">Irmandade <span className="text-yellow-500">na Estrada</span></h2>
                     <p className="text-zinc-400 font-bold uppercase tracking-[0.3em] text-xs md:text-sm">Explorando as rotas mais icônicas do planeta.</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 space-y-4">
                     <Trophy className="text-yellow-500" size={32} />
                     <h3 className="text-xl font-oswald font-black uppercase italic">Elite L.A.M.A.</h3>
                     <p className="text-zinc-500 text-sm">Acesso exclusivo às rotas testadas e aprovadas pelo motoclube.</p>
                  </div>
                  <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 space-y-4">
