      return;
    }
    setIsUpdating(true);

    try {
      const formattedBirthDate = editForm.birthDate && editForm.birthDate.trim() !== "" 
        ? editForm.birthDate 
        : null;

      // 1. Database Update (Profiles)
      const { error: dbError } = await supabase
        .from('profiles')
        .upsert({
          id: user.id,
          name: editForm.name,
          bike_model: editForm.bikeModel,
          avatar_url: editForm.avatar,
          birth_date: formattedBirthDate,
          updated_at: new Date().toISOString()
        }, {
          onConflict: 'id'
        });

      if (dbError) throw dbError;

      // 2. Auth Metadata Update
      const { error: authError } = await supabase.auth.updateUser({
        data: {
          name: editForm.name,
          bikeModel: editForm.bikeModel
        }
      });

      if (authError) throw authError;

      // Local state update
      setIsEditingProfile(false);
      setUser({ 
        ...user, 
        name: editForm.name, 
        bikeModel: editForm.bikeModel, 
        avatar: editForm.avatar, 
        birthDate: formattedBirthDate || "" 
      });
      alert("Perfil atualizado com sucesso!");
    } catch (err: any) {
      console.error("Erro detalhado ao salvar perfil:", err);
      const msg = formatError(err);
      alert(`Erro detalhado ao salvar perfil:\n${msg}`);
    } finally {
      setIsUpdating(false);
