          bike_model: editForm.bikeModel,
          avatar_url: editForm.avatar,
          birth_date: formattedBirthDate,
          updated_at: new Date().toISOString()
        }, {
          onConflict: 'id'
        });

      if (dbError) throw dbError;

      // 2. Atualização nos metadados de autenticação
