        : null;

      // 1. Atualização no banco de dados (tabela profiles)
      const { error: dbError } = await supabase
        .from('profiles')
        .upsert({
          id: user.id,
          name: editForm.name,
          bike_model: editForm.bikeModel,
          avatar_url: editForm.avatar,
          birth_date: formattedBirthDate,
          updated_at: new Date().toISOString()
