          onConflict: 'id'
        });

      if (dbError) throw dbError;

      // 2. Atualização nos metadados de autenticação
      const { error: authError } = await supabase.auth.updateUser({
        data: {
          name: editForm.name,
          bikeModel: editForm.bikeModel
