const sanitizeEnv = (val?: string) => val?.replace(/['"]/g, '').trim() || '';

// Nota: Estas credenciais são fallbacks. O ideal é que o usuário configure SUPABASE_URL e SUPABASE_ANON_KEY no ambiente.
const supabaseUrl = sanitizeEnv(process.env.SUPABASE_URL || 'https://lvlflziahcthajmlgmme.supabase.co');
const supabaseAnonKey = sanitizeEnv(process.env.SUPABASE_ANON_KEY || 'sb_publishable_4REfrYkRKt-FLbLetrbagw_bvu-JItj');

if (!supabaseUrl || supabaseUrl.includes('placeholder')) {
  console.error("Configuração de URL do Supabase inválida ou ausente.");
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storage: window.localStorage
  },
  global: {
    headers: { 'x-application-name': 'lama-aparecida-motos' }
  },
  // Aumentar o timeout e melhorar a resiliência para evitar 'Failed to fetch' em conexões lentas ou instáveis
  db: {
