  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    // Tratamento especial para erro de rede 'Failed to fetch'
    if (err.message === 'Failed to fetch' || err.message?.includes('fetch')) {
      return "Falha de Conexão: O servidor do Supabase não pôde ser alcançado. Verifique se o endereço SUPABASE_URL está correto e se você tem internet. Se estiver usando uma rede corporativa, ela pode estar bloqueando o domínio supabase.co.";
    }

    const message = err.message || err.error_description || err.msg || err.error;
    if (message && typeof message === 'string') return message;

    try {
      return JSON.stringify(err, null, 2);
    } catch (e) {
      return String(err);
    }
  };

