      return;
    }

    setIsUpdating(true);

    try {
      // Diagnóstico prévio de conexão
      const conn = await checkSupabaseConnection();
      if (!conn.ok) {
        throw new Error(`O aplicativo não consegue falar com o Supabase. Verifique sua rede e a variável SUPABASE_URL. Erro original: ${conn.error}`);
      }

      const formattedBirthDate = editForm.birthDate && editForm.birthDate.trim() !== "" 
        ? editForm.birthDate 
        : null;

      // 1. Atualização no banco de dados (tabela profiles)
      // Esta é a parte mais crítica que pode falhar com payload grande
      const { error: dbError } = await supabase
        .from('profiles')
        .upsert({
          id: user.id,
          name: editForm.name,
          bike_model: editForm.bikeModel,
          avatar_url: editForm.avatar,
          birth_date: formattedBirthDate,
          updated_at: new Date().toISOString()
        }, {
          onConflict: 'id'
        });

      if (dbError) {
        console.error("Erro na tabela Profiles:", dbError);
        throw dbError;
      }

      // 2. Atualização nos metadados de autenticação (somente campos leves)
      // Evitamos enviar o avatar base64 aqui para não sobrecarregar o Auth meta_data
      const { error: authError } = await supabase.auth.updateUser({
        data: {
          name: editForm.name,
          bikeModel: editForm.bikeModel
          // avatar_url removido daqui de propósito para evitar Failed to fetch em navegadores com proxy
        }
      });

      if (authError) {
        console.warn("Aviso: Dados salvos no banco, mas erro ao atualizar metadados de Auth:", authError);
        // Não jogamos erro aqui pois o banco já foi atualizado com sucesso
      }

      // Sucesso: atualiza estado local
      setIsEditingProfile(false);
      setUser({ 
        ...user, 
        name: editForm.name, 
        bikeModel: editForm.bikeModel, 
        avatar: editForm.avatar, 
        birthDate: formattedBirthDate || "" 
      });
      alert("Perfil atualizado com sucesso!");
    } catch (err: any) {
      console.error("Falha crítica no salvamento:", err);
