const sanitizeEnv = (val?: string) => val?.replace(/['"]/g, '').trim() || '';

const supabaseUrl = sanitizeEnv(process.env.SUPABASE_URL || 'https://lvlflziahcthajmlgmme.supabase.co');
const supabaseAnonKey = sanitizeEnv(process.env.SUPABASE_ANON_KEY || 'sb_publishable_4REfrYkRKt-FLbLetrbagw_bvu-JItj');

// Debug log apenas em desenvolvimento ou se a URL parecer suspeita
if (!supabaseUrl || supabaseUrl.includes('placeholder') || !supabaseUrl.startsWith('http')) {
  console.warn("⚠️ ALERTA: SUPABASE_URL parece inválida:", supabaseUrl);
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storage: window.localStorage
  },
  global: {
    headers: { 'x-application-name': 'lama-aparecida-motos' }
  },
  db: {
    schema: 'public'
  }
});

// Helper para verificar se a conexão está ativa (útil para debug de 'Failed to fetch')
export const checkSupabaseConnection = async () => {
  try {
    // Tenta uma operação ultra simples de ping
    const { error } = await supabase.from('profiles').select('id').limit(1);
    if (error) {
      // Se o erro for de conexão, o fetch falha antes de retornar o objeto error
      return { ok: false, error: error.message, code: error.code };
    }
    return { ok: true };
  } catch (err: any) {
    return { ok: false, error: err.message || "Erro de rede (DNS ou bloqueio)" };
  }
};

