   */
  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    // Tratamento especial para erro de rede 'Failed to fetch'
    if (err.message === 'Failed to fetch' || err.message?.includes('fetch') || err.name === 'TypeError') {
      return "⚠️ FALHA DE CONEXÃO: O navegador não conseguiu conversar com o Supabase.\n\nProváveis causas:\n1. SUPABASE_URL configurada errada.\n2. Sua internet caiu.\n3. O domínio do Supabase está bloqueado pela sua rede/VPN.";
    }

    const message = err.message || err.error_description || err.msg || err.error;
    if (message && typeof message === 'string') return message;

    try {
      return JSON.stringify(err, null, 2);
    } catch (e) {
      return String(err);
    }
  };

