import { createClient } from '@supabase/supabase-js';

// Sanitização: remove espaços e aspas extras das variáveis de ambiente
const sanitizeEnv = (val?: string) => val?.trim().replace(/['"]/g, '') || '';

const supabaseUrl = sanitizeEnv(process.env.SUPABASE_URL || 'https://lvlflziahcthajmlgmme.supabase.co');
const supabaseAnonKey = sanitizeEnv(process.env.SUPABASE_ANON_KEY || 'sb_publishable_4REfrYkRKt-FLbLetrbagw_bvu-JItj');

// Validação básica para o console do desenvolvedor
if (!supabaseUrl.startsWith('https://')) {
  console.error("ERRO DE CONFIGURAÇÃO: SUPABASE_URL deve começar com https://. Valor atual:", supabaseUrl);
}

// O Supabase Anon Key deve ser um JWT longo (começa com eyJ...). 
