export const checkSupabaseConnection = async () => {
  try {
    console.log("Iniciando teste de conexão com:", supabaseUrl);
    const { error } = await supabase.from('profiles').select('id').limit(1);
    if (error) {
      console.error("Erro de resposta do Supabase:", error);
      return { ok: false, error: error.message };
    }
    return { ok: true };
  } catch (err: any) {
    console.error("Falha de rede ao contactar Supabase:", err);
    return { 
      ok: false, 
      error: "O navegador bloqueou a conexão (Failed to fetch).",
      details: "Isso geralmente significa que a URL '" + supabaseUrl + "' é inválida ou o servidor está offline."
    };
  }
};

