  const formatError = (err: any): string => {
    if (!err) return "Erro desconhecido";
    if (typeof err === 'string') return err;

    if (err.message === 'Failed to fetch' || err.name === 'TypeError') {
      return "⚠️ FALHA DE REDE: O navegador impediu a conexão.\n\nPossíveis causas:\n1. URL do Supabase incorreta.\n2. Sua internet oscilou.\n3. O servidor do Supabase está offline ou bloqueando sua rede.";
    }

    const message = err.message || err.error_description || err.msg || err.error;
    if (message && typeof message === 'string') return message;

    try {
      return JSON.stringify(err, null, 2);
    } catch (e) {
      return String(err);
