import { createClient } from '@supabase/supabase-js';

// Função de limpeza para evitar que aspas ou espaços quebrem a URL/Key
const clean = (val?: string) => {
  if (!val) return '';
  return val.trim().replace(/['"]/g, '');
};

// Prioriza variáveis definidas no ambiente, com fallbacks explícitos
const supabaseUrl = clean(process.env.SUPABASE_URL) || 'https://lvlflziahcthajmlgmme.supabase.co';
const supabaseAnonKey = clean(process.env.SUPABASE_ANON_KEY) || '';

// Validação proativa
if (!supabaseUrl.startsWith('https://')) {
  console.error("⚠️ ERRO: SUPABASE_URL deve ser uma URL válida (https://...).");
}

if (!supabaseAnonKey || supabaseAnonKey.length < 20) {
  console.error("⚠️ ERRO: SUPABASE_ANON_KEY parece ausente ou inválida. Certifique-se de configurar as variáveis de ambiente no Vercel/Ambiente de Deploy.");
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storage: window.localStorage
  },
  global: {
    // Desativar cache para garantir que diagnósticos reflitam o estado atual do servidor
    fetch: (url, options) => fetch(url, { ...options, cache: 'no-store' })
  }
});

/**
 * Diagnóstico de conexão aprimorado.
 * Tenta realizar uma consulta leve e captura erros de rede específicos.
 */
export const checkSupabaseConnection = async () => {
  try {
    const { error, status } = await supabase.from('profiles').select('id').limit(1);

    if (error) {
      // Erro retornado pelo servidor Supabase (ex: 401, 403, 404)
      console.error("Resposta de erro do servidor Supabase:", error);
      return { 
        ok: false, 
        error: error.message || "Erro de permissão/configuração no servidor.",
        code: error.code,
        status 
      };
    }

    return { ok: true };
  } catch (err: any) {
    // Erro de rede (ex: DNS, CORS, Offline, URL Inválida)
    console.error("Falha física de rede (Fetch Error):", err);
    return { 
      ok: false, 
      error: "O navegador bloqueou a conexão (TypeError: Failed to fetch).",
      details: "Causas comuns: URL '" + supabaseUrl + "' incorreta, falta de internet, ou bloqueio por políticas de segurança (CORS/Firewall)."
    };
  }
};

