import { createClient } from '@supabase/supabase-js';

// Função de limpeza para evitar que aspas ou espaços quebrem a URL/Key
const clean = (val?: string) => {
  if (!val) return '';
  return val.trim().replace(/['"]/g, '');
};

// Prioriza variáveis definidas no ambiente, com fallbacks explícitos para o projeto L.A.M.A.
const supabaseUrl = clean(process.env.SUPABASE_URL) || 'https://lvlflziahcthajmlgmme.supabase.co';
const supabaseAnonKey = clean(process.env.SUPABASE_ANON_KEY) || 'sb_publishable_4REfrYkRKt-FLbLetrbagw_bvu-JItj';

// Validação proativa no console para ajudar no deploy
if (!supabaseUrl || !supabaseUrl.startsWith('https://')) {
  console.error("⚠️ ERRO: SUPABASE_URL ausente ou inválida.");
}

if (!supabaseAnonKey) {
  console.error("⚠️ ERRO: SUPABASE_ANON_KEY ausente. O app não conseguirá se conectar ao banco.");
}

/**
 * Inicialização do cliente Supabase.
 * Se a chave estiver ausente, retornamos um proxy ou null para evitar o "Uncaught Error: supabaseKey is required"
 * que impede o carregamento de qualquer parte do React.
 */
const createSafeClient = () => {
  if (!supabaseUrl || !supabaseAnonKey) {
    console.warn("⚠️ Supabase Client inicializado com chaves vazias. Algumas funções podem falhar.");
    // Retornamos um objeto que não quebra o carregamento, mas falha nas requisições
    return createClient(
      supabaseUrl || 'https://placeholder.supabase.co', 
      supabaseAnonKey || 'placeholder-key'
    );
  }

  return createClient(supabaseUrl, supabaseAnonKey, {
    auth: {
      persistSession: true,
      autoRefreshToken: true,
      detectSessionInUrl: true,
      storage: window.localStorage
    },
    global: {
      fetch: (url, options) => fetch(url, { ...options, cache: 'no-store' })
    }
  });
};

export const supabase = createSafeClient();

/**
 * Diagnóstico de conexão aprimorado.
 */
export const checkSupabaseConnection = async () => {
  if (!supabaseAnonKey || supabaseAnonKey === 'placeholder-key') {
    return { 
      ok: false, 
      error: "Configuração ausente.", 
      details: "As chaves do Supabase não foram encontradas nas variáveis de ambiente." 
    };
  }

  try {
    const { error, status } = await supabase.from('profiles').select('id').limit(1);

    if (error) {
      console.error("Resposta de erro do servidor Supabase:", error);
      return { 
        ok: false, 
        error: error.message || "Erro de permissão no servidor.",
        code: error.code,
        status 
      };
    }

    return { ok: true };
  } catch (err: any) {
    console.error("Falha física de rede (Fetch Error):", err);
    return { 
      ok: false, 
      error: "Falha de conexão (TypeError: Failed to fetch).",
      details: "Verifique se a URL '" + supabaseUrl + "' está correta e se há conexão com a internet."
    };
  }
};

