Para resetarmos tudo e garantir que o sistema funcione sem erros de "Failed to fetch" (que geralmente ocorrem por payload excessivo ou falta de permissões RLS) e sem conflitos de tabelas, siga estes passos.

### Passo 1: O Script SQL "Nuclear"
Copie e cole este script no **SQL Editor** do seu painel Supabase. Ele vai apagar tudo e recriar do zero com as permissões corretas.

```sql
-- 1. LIMPEZA TOTAL (Cuidado: apaga os dados existentes)
drop trigger if exists on_auth_user_created on auth.users;
drop function if exists public.handle_new_user();
drop table if exists public.routes;
drop table if exists public.profiles;

-- 2. CRIAÇÃO DA TABELA DE PERFIS
create table public.profiles (
  id uuid references auth.users on delete cascade not null primary key,
  name text,
  bike_model text,
  avatar_url text, -- Aqui vamos limitar o tamanho no App.tsx
  birth_date date,
  role text default 'member',
  updated_at timestamp with time zone default now()
);

-- 3. CRIAÇÃO DA TABELA DE ROTAS
create table public.routes (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users on delete cascade,
  title text not null,
  description text,
  distance text,
  difficulty text,
  points jsonb default '[]'::jsonb,
  status text default 'planejada',
  thumbnail text,
  is_official boolean default false,
  created_at timestamp with time zone default now()
);

-- 4. HABILITAR SEGURANÇA (RLS)
alter table public.profiles enable row level security;
alter table public.routes enable row level security;

-- 5. POLÍTICAS DE ACESSO (PERFIS)
create policy "Público pode ver perfis" on public.profiles for select using (true);
create policy "Dono pode inserir perfil" on public.profiles for insert with check (auth.uid() = id);
create policy "Dono pode atualizar perfil" on public.profiles for update using (auth.uid() = id);

-- 6. POLÍTICAS DE ACESSO (ROTAS)
create policy "Público pode ver rotas" on public.routes for select using (true);
create policy "Usuário autenticado cria rotas" on public.routes for insert with check (auth.uid() = user_id);
create policy "Dono deleta rota" on public.routes for delete using (auth.uid() = user_id);

-- 7. GATILHO PARA CRIAR PERFIL AUTOMÁTICO NO SIGNUP
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, name, bike_model, role)
  values (
    new.id, 
    coalesce(new.raw_user_meta_data->>'name', 'Membro L.A.M.A.'),
    coalesce(new.raw_user_meta_data->>'bikeModel', 'Não informada'),
    coalesce(new.raw_user_meta_data->>'role', 'member')
  );
  return new;
end;
$$ language plpgsql security definer;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();
```

