    if (typeof err === 'string') return err;
    const message = err.message || err.error_description || (typeof err === 'object' ? JSON.stringify(err) : String(err));
    if (message.includes('Failed to fetch')) {
      return "⚠️ FALHA DE REDE: O navegador impediu a conexão.\n\nPossíveis causas:\n1. URL do Supabase incorreta.\n2. Sua internet oscilou.\n3. O servidor do Supabase está offline ou bloqueando sua rede.";
    }
