      case 'Moderada': return 'bg-yellow-500 text-black border-yellow-600 shadow-[0_0_10px_rgba(234,179,8,0.3)]';
      case 'Difícil': return 'bg-orange-700 text-white border-orange-800 shadow-[0_0_10px_rgba(194,65,12,0.3)]';
