// Simulação completa do Supabase usando LocalStorage
// Mantém a compatibilidade de tipos para não quebrar o App.tsx

const STORAGE_KEYS = {
  USERS: 'lama_local_users',
  PROFILES: 'lama_local_profiles',
  ROUTES: 'lama_local_routes',
  SESSION: 'lama_local_session'
};

// Dados Iniciais / Auxiliares
const getLocal = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
const setLocal = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

const SUPERUSER_EMAIL = 'lama.aparecidabr@gmail.com';

export const supabase: any = {
  auth: {
    getSession: async () => {
      const session = JSON.parse(localStorage.getItem(STORAGE_KEYS.SESSION) || 'null');
      return { data: { session }, error: null };
    },
    signInWithPassword: async ({ email, password }: any) => {
      const users = getLocal(STORAGE_KEYS.USERS);
      const user = users.find((u: any) => u.email === email && u.password === password);

      if (user) {
        const session = { user };
        localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
        return { data: { session }, error: null };
      }

      // Se for o primeiro login do Admin e não existir, criamos automaticamente para facilitar
      if (email === SUPERUSER_EMAIL) {
         const adminUser = { id: 'admin-id', email: SUPERUSER_EMAIL, user_metadata: { name: 'Admin L.A.M.A.' } };
         users.push({ ...adminUser, password });
         setLocal(STORAGE_KEYS.USERS, users);
         const session = { user: adminUser };
         localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
         return { data: { session }, error: null };
      }

      return { data: { session: null }, error: { message: "Credenciais inválidas no banco local." } };
    },
    signUp: async ({ email, password, options }: any) => {
      const users = getLocal(STORAGE_KEYS.USERS);
      if (users.find((u: any) => u.email === email)) {
        return { data: { user: null }, error: { message: "Usuário já registrado localmente." } };
      }
      const newUser = { 
        id: Math.random().toString(36).substr(2, 9), 
        email, 
        user_metadata: options?.data || {} 
      };
      users.push({ ...newUser, password });
      setLocal(STORAGE_KEYS.USERS, users);
      return { data: { user: newUser }, error: null };
    },
    signOut: async () => {
      localStorage.removeItem(STORAGE_KEYS.SESSION);
      return { error: null };
    },
    updateUser: async ({ data }: any) => {
      const session = JSON.parse(localStorage.getItem(STORAGE_KEYS.SESSION) || 'null');
      if (session) {
        session.user.user_metadata = { ...session.user.user_metadata, ...data };
        localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      }
      return { data: session, error: null };
    },
    onAuthStateChange: (callback: any) => {
      // Simulação simples de evento
      return { data: { subscription: { unsubscribe: () => {} } } };
    }
  },

  from: (table: string) => {
    return {
      select: (columns: string) => ({
        eq: (column: string, value: any) => ({
          maybeSingle: async () => {
            const data = getLocal(table === 'profiles' ? STORAGE_KEYS.PROFILES : STORAGE_KEYS.ROUTES);
            const item = data.find((i: any) => i[column] === value);
            return { data: item || null, error: null };
          },
          order: (col: string, { ascending }: any) => ({
            data: getLocal(table === 'profiles' ? STORAGE_KEYS.PROFILES : STORAGE_KEYS.ROUTES)
              .filter((i: any) => i[column] === value)
              .sort((a: any, b: any) => ascending ? a[col] - b[col] : b[col] - a[col]),
            error: null
          })
        }),
        order: (col: string, { ascending }: any) => {
          const data = getLocal(table === 'profiles' ? STORAGE_KEYS.PROFILES : STORAGE_KEYS.ROUTES);
          const sorted = data.sort((a: any, b: any) => {
            const valA = a[col] || '';
            const valB = b[col] || '';
            return ascending ? (valA > valB ? 1 : -1) : (valA < valB ? 1 : -1);
          });
          return { data: sorted, error: null };
        }
      }),
      upsert: async (newItem: any) => {
        const key = table === 'profiles' ? STORAGE_KEYS.PROFILES : STORAGE_KEYS.ROUTES;
        const data = getLocal(key);
        const index = data.findIndex((i: any) => i.id === newItem.id);

        // Regra de Admin automática baseada no email na tabela de perfis
        if (table === 'profiles') {
          const session = JSON.parse(localStorage.getItem(STORAGE_KEYS.SESSION) || 'null');
          if (session?.user?.email === SUPERUSER_EMAIL) {
            newItem.role = 'admin';
          }
        }

        if (index > -1) data[index] = { ...data[index], ...newItem };
        else data.push(newItem);
        setLocal(key, data);
        return { error: null };
      },
      insert: async (newItems: any[]) => {
        const key = table === 'profiles' ? STORAGE_KEYS.PROFILES : STORAGE_KEYS.ROUTES;
        const data = getLocal(key);
        newItems.forEach(item => {
          data.push({ id: Math.random().toString(36).substr(2, 9), ...item, created_at: new Date().toISOString() });
        });
        setLocal(key, data);
        return { error: null };
      },
      delete: () => ({
        eq: (column: string, value: any) => {
          const key = table === 'profiles' ? STORAGE_KEYS.PROFILES : STORAGE_KEYS.ROUTES;
          const data = getLocal(key);
          const filtered = data.filter((i: any) => i[column] !== value);
          setLocal(key, filtered);
          return { error: null };
        }
      })
    };
  }
};

