/**
 * L.A.M.A. LOCAL ENGINE
 * Substitui completamente o Supabase por persistência em LocalStorage.
 * Desvinculado de serviços de nuvem para evitar erros de conexão.
 */

const KEYS = {
  USERS: 'lama_db_users',
  PROFILES: 'lama_db_profiles',
  ROUTES: 'lama_db_routes',
  SESSION: 'lama_db_session'
};

const getDB = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
const setDB = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

export const supabase: any = {
  auth: {
    getSession: async () => {
      const session = JSON.parse(localStorage.getItem(KEYS.SESSION) || 'null');
      return { data: { session }, error: null };
    },
    signInWithPassword: async ({ email, password }: any) => {
      const users = getDB(KEYS.USERS);
      const user = users.find((u: any) => u.email === email && u.password === password);

      if (user) {
        const session = { user };
        localStorage.setItem(KEYS.SESSION, JSON.stringify(session));
        return { data: { session }, error: null };
      }

      // Auto-criação do Admin se for o primeiro acesso
      if (email === ADMIN_EMAIL) {
        const adminUser = { 
          id: 'admin_master', 
          email: ADMIN_EMAIL, 
          user_metadata: { name: 'Membro L.A.M.A. Admin' } 
        };
        users.push({ ...adminUser, password });
        setDB(KEYS.USERS, users);
        const session = { user: adminUser };
        localStorage.setItem(KEYS.SESSION, JSON.stringify(session));
        return { data: { session }, error: null };
      }

      return { data: { session: null }, error: { message: "Credenciais não encontradas no sistema local." } };
    },
    signUp: async ({ email, password, options }: any) => {
      const users = getDB(KEYS.USERS);
      if (users.find((u: any) => u.email === email)) {
        return { data: { user: null }, error: { message: "Piloto já cadastrado." } };
      }
      const newUser = { 
        id: Math.random().toString(36).substr(2, 9), 
        email, 
        user_metadata: options?.data || {} 
      };
      users.push({ ...newUser, password });
      setDB(KEYS.USERS, users);
      return { data: { user: newUser }, error: null };
    },
    signOut: async () => {
      localStorage.removeItem(KEYS.SESSION);
      return { error: null };
    },
    updateUser: async ({ data }: any) => {
      const session = JSON.parse(localStorage.getItem(KEYS.SESSION) || 'null');
      if (session) {
        session.user.user_metadata = { ...session.user.user_metadata, ...data };
        localStorage.setItem(KEYS.SESSION, JSON.stringify(session));
      }
      return { data: session, error: null };
    },
    onAuthStateChange: () => ({ data: { subscription: { unsubscribe: () => {} } } })
  },

  from: (table: string) => {
    const tableKey = table === 'profiles' ? KEYS.PROFILES : KEYS.ROUTES;
    return {
      select: () => ({
        eq: (col: string, val: any) => ({
          maybeSingle: async () => {
            const data = getDB(tableKey);
            const item = data.find((i: any) => i[col] === val);
            return { data: item || null, error: null };
          }
        }),
        order: (col: string, { ascending }: any = {}) => {
          const data = getDB(tableKey);
          const sorted = [...data].sort((a, b) => {
            if (ascending) return a[col] > b[col] ? 1 : -1;
            return a[col] < b[col] ? 1 : -1;
          });
          return { data: sorted, error: null };
        }
      }),
      upsert: async (item: any) => {
        const data = getDB(tableKey);
        const index = data.findIndex((i: any) => i.id === item.id);

        // Lógica de Role baseada no Admin Email
        if (table === 'profiles') {
          const session = JSON.parse(localStorage.getItem(KEYS.SESSION) || 'null');
          if (session?.user?.email === ADMIN_EMAIL) {
            item.role = 'admin';
          }
        }

        if (index > -1) data[index] = { ...data[index], ...item };
        else data.push(item);
        setDB(tableKey, data);
        return { error: null };
      },
      insert: async (items: any[]) => {
        const data = getDB(tableKey);
        items.forEach(item => {
          data.push({ 
            id: Math.random().toString(36).substr(2, 9), 
            ...item, 
            created_at: new Date().toISOString() 
          });
        });
        setDB(tableKey, data);
        return { error: null };
      },
      delete: () => ({
        eq: (col: string, val: any) => {
          const data = getDB(tableKey);
          const filtered = data.filter((i: any) => i[col] !== val);
          setDB(tableKey, filtered);
          return { error: null };
        }
      })
    };
  }
};

