      console.error("Erro ao obter insights via Gemini:", error);
      alert("Radar temporariamente indisponível. Tente novamente mais tarde.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
    setUser(null);
    setView('home');
  };

