      case 'Fácil': return 'text-green-400 border-green-400/30 bg-green-500/10 shadow-[0_0_10px_rgba(74,222,128,0.2)]';
      default: return 'text-zinc-400 border-zinc-800 bg-zinc-800/30';
    }
  };

