const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [editForm, setEditForm] = useState({ name: '', bikeModel: '', avatar: '', birthDate: '' });
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isSyncingRef = useRef(false);

  // Monitor de Autenticação Robusto com Fallback de Segurança
  useEffect(() => {
    let mounted = true;

    // Timer de Segurança: Se em 4 segundos o Supabase não responder, libera a tela de qualquer forma
    const safetyTimeout = setTimeout(() => {
      if (mounted && isLoading) {
        console.warn("Auth initialization safety timeout triggered.");
        setIsLoading(false);
      }
    }, 4000);

    const initSession = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user && mounted) {
          await syncUserData(session.user);
        } else if (mounted) {
          setIsLoading(false);
        }
      } catch (error) {
        console.error("Erro ao inicializar sessão:", error);
        if (mounted) setIsLoading(false);
      }
    };

    initSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;

      if (session?.user) {
        // Se já estamos sincronizando pelo initSession, não fazemos nada aqui para evitar duplicidade
        if (!isSyncingRef.current) {
          await syncUserData(session.user);
        }
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setRoutes([]);
        setLoginForm({ email: '', password: '' });
        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      clearTimeout(safetyTimeout);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) fetchRoutes();
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    if (isSyncingRef.current) return;
    isSyncingRef.current = true;

    try {
      const { data: profile, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      if (error) throw error;

      const userData: User = {
        id: authUser.id,
        name: profile?.name || authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        bikeModel: profile?.bike_model || 'Não informado',
        avatar: profile?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        birthDate: profile?.birth_date || '',
        role: (profile?.role as 'admin' | 'member') || (authUser.email === ADMIN_EMAIL ? 'admin' : 'member')
      };

      setUser(userData);
      setEditForm({
        name: userData.name,
        bikeModel: userData.bikeModel || '',
        avatar: userData.avatar || '',
        birthDate: userData.birthDate || ''
      });
      setIsAuthenticated(true);
    } catch (err) {
      console.error("Erro ao sincronizar perfil:", err);
      if (authUser) setIsAuthenticated(true);
    } finally {
      setIsLoading(false);
      isSyncingRef.current = false;
    }
  };

  const fetchRoutes = async () => {
    const { data, error } = await supabase
      .from('routes')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error("Erro ao buscar rotas:", error);
      return;
    }

    if (data) {
      setRoutes(data.map((r: any) => ({
        id: r.id,
        user_id: r.user_id,
        title: r.title,
        description: r.description,
        distance: r.distance,
        difficulty: r.difficulty,
        points: r.points,
        status: r.status,
        thumbnail: r.thumbnail,
        isOfficial: r.is_official
      })));
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword(loginForm);
      if (error) {
        alert("Acesso negado: " + error.message);
        setIsLoading(false);
      }
    } catch (err) {
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);

    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate || null,
        updated_at: new Date().toISOString()
      });

      if (error) throw error;

      setUser({ ...user, ...editForm });
      setIsEditingProfile(false);
      alert("Perfil atualizado com sucesso!");
    } catch (err: any) {
      alert("Erro ao atualizar perfil: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handlePasswordChange = async () => {
    const newPassword = window.prompt("Digite sua nova senha (mínimo 6 caracteres):");
    if (newPassword === null) return;

    if (newPassword.length < 6) {
      alert("A senha deve conter pelo menos 6 caracteres.");
      return;
    }

    setIsUpdating(true);
    try {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) throw error;
      alert("Senha alterada com sucesso!");
    } catch (err: any) {
      alert("Erro ao alterar senha: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("A imagem deve ter no máximo 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
