                      </div>
                    </div>
                    <MapView points={[{...CLUBHOUSE_COORDS, timestamp: Date.now()}]} className="h-[400px] shadow-3xl" isInteractive />
                  </div>
                </div>
              )}

              {currentView === 'gallery' && (
