    thumbnail: 'https://images.unsplash.com/photo-1540541338287-41700207dee6?q=80&w=800&auto=format&fit=crop',
    isOfficial: false
  }
];

const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [allMembers, setAllMembers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [editForm, setEditForm] = useState({ name: '', bikeModel: '', avatar: '', birthDate: '', associationType: '' as any });
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const syncInProgress = useRef(false);

  useEffect(() => {
    let mounted = true;

    const safetyTimer = setTimeout(() => {
      if (mounted && isLoading) {
        setIsLoading(false);
      }
    }, 8000);

    const checkInitialSession = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (mounted) {
          if (session?.user) {
            await syncUserData(session.user);
          } else {
            setIsLoading(false);
          }
        }
      } catch (err) {
        if (mounted) setIsLoading(false);
      }
    };

    checkInitialSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;

      if (session?.user) {
        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setRoutes([]);
        setAllMembers([]);
        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      clearTimeout(safetyTimer);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    if (syncInProgress.current) return;
    syncInProgress.current = true;

    try {
      const profilePromise = supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error("Conexão instável")), 15000)
      );

      let profileData = null;
      try {
        const result: any = await Promise.race([profilePromise, timeoutPromise]);
        profileData = result?.data || null;
      } catch (e) {
        console.warn("Radar lento: usando dados básicos de autenticação.");
      }

      const userData: User = {
        id: authUser.id,
        name: profileData?.name || authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        bikeModel: profileData?.bike_model || 'Não informado',
        avatar: profileData?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        birthDate: profileData?.birth_date || '',
        associationType: profileData?.association_type || undefined,
        role: (profileData?.role as 'admin' | 'member') || (authUser.email === ADMIN_EMAIL ? 'admin' : 'member')
      };

      setUser(userData);
      setEditForm({
        name: userData.name,
        bikeModel: userData.bikeModel || '',
        avatar: userData.avatar || '',
        birthDate: userData.birthDate || '',
        associationType: userData.associationType || ''
      });
      setIsAuthenticated(true);
    } catch (err) {
      setIsAuthenticated(true);
    } finally {
      setIsLoading(false);
      syncInProgress.current = false;
    }
  };

  const fetchMembers = async () => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('id, name, avatar_url, birth_date, bike_model, association_type')
        .order('name', { ascending: true });

      if (error) throw error;
      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: '' // Não expomos email por privacidade
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar membros:", err);
    }
  };

  const fetchRoutes = async () => {
    try {
      const { data, error } = await supabase
        .from('routes')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;

      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: r.points,
          status: r.status,
          thumbnail: r.thumbnail,
          isOfficial: r.is_official
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar rotas:", err);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword(loginForm);
      if (error) {
        alert("Acesso negado: " + error.message);
        setIsLoading(false);
      }
    } catch (err: any) {
      alert("Erro inesperado no login.");
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);

    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate || null,
        association_type: editForm.associationType || null,
        updated_at: new Date().toISOString()
      });

      if (error) throw error;

      setUser({ ...user, ...editForm });
      setIsEditingProfile(false);
      fetchMembers(); // Atualiza lista
      alert("Perfil atualizado com sucesso!");
    } catch (err: any) {
      alert("Erro ao atualizar perfil: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handlePasswordChange = async () => {
    const newPassword = window.prompt("Digite sua nova senha (mínimo 6 caracteres):");
    if (newPassword === null) return;

    if (newPassword.length < 6) {
      alert("A senha deve conter pelo menos 6 caracteres.");
      return;
    }

    setIsUpdating(true);
    try {
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) throw error;
      alert("Senha alterada com sucesso!");
    } catch (err: any) {
      alert("Erro ao alterar senha: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("A imagem deve ter no máximo 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;

    const { error } = await supabase.from('routes').insert([{
      id: newRoute.id,
      user_id: user.id,
      title: newRoute.title,
      description: newRoute.description,
      distance: newRoute.distance,
      difficulty: newRoute.difficulty,
      points: newRoute.points,
      status: newRoute.status,
      thumbnail: newRoute.thumbnail,
      is_official: user.role === 'admin'
    }]);

    if (error) {
      alert("Erro ao salvar missão no banco: " + error.message);
    } else {
      fetchRoutes();
    }
  };

  const fetchInsights = async (route: Route) => {
    setIsUpdating(true);
    try {
      const data = await getRouteInsights(route.title, "Aparecida de Goiânia, GO");
      alert(`🛡️ DICAS L.A.M.A. PARA: ${route.title}\n\n${data.safetyTips.map((t: string) => `• ${t}`).join('\n')}\n\n🌅 DESTAQUE PAISAGÍSTICO: ${data.scenicHighlight}`);
    } catch (error) {
      console.error("Erro ao obter insights via Gemini:", error);
      alert("Radar temporariamente indisponível. Tente novamente mais tarde.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleLogout = async () => {
    try {
      await supabase.auth.signOut();
    } catch (error) {
      console.error("Logout error:", error);
    } finally {
      setIsAuthenticated(false);
      setUser(null);
      setRoutes([]);
      setAllMembers([]);
      setView('home');
      setIsLoading(false);
    }
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(JSON.stringify({ 
        event: 'command', 
        func: command, 
        args: [] 
      }), '*');

      if (isMuted) {
        videoRef.current.contentWindow.postMessage(JSON.stringify({ 
          event: 'command', 
          func: 'setVolume', 
          args: [100] 
        }), '*');
      }
      setIsMuted(!isMuted);
    }
  };

  const handleFullscreen = () => {
    if (videoContainerRef.current) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        videoContainerRef.current.requestFullscreen().catch(err => {
          console.error(`Erro ao tentar ativar tela cheia: ${err.message}`);
        });
      }
    }
  };

  const getDifficultyStyles = (difficulty: string) => {
    switch (difficulty) {
      case 'Lendária': return 'text-red-500 border-red-500/30 bg-red-500/10 shadow-[0_0_10px_rgba(239,68,68,0.3)]';
      case 'Difícil': return 'text-orange-600 border-orange-600/30 bg-orange-600/10 shadow-[0_0_10px_rgba(234,88,12,0.3)]';
      case 'Moderada': return 'text-yellow-500 border-yellow-500/30 bg-yellow-500/10 shadow-[0_0_10px_rgba(234,179,8,0.2)]';
      case 'Fácil': return 'text-green-400 border-green-400/30 bg-green-500/10 shadow-[0_0_10px_rgba(74,222,128,0.2)]';
      default: return 'text-zinc-400 border-zinc-800 bg-zinc-800/30';
    }
  };

  const formatDate = (dateString?: string) => {
    if (!dateString) return 'Não informado';
    const [year, month, day] = dateString.split('-');
    return `${day}/${month}/${year}`;
  };

  const getBirthdays = (targetMonthOffset: number) => {
    const now = new Date();
    const targetMonth = (now.getMonth() + targetMonthOffset) % 12;

    return allMembers.filter(m => {
      if (!m.birthDate) return false;
      const bDate = new Date(m.birthDate);
      return bDate.getUTCMonth() === targetMonth;
    }).sort((a, b) => {
      const dayA = new Date(a.birthDate!).getUTCDate();
      const dayB = new Date(b.birthDate!).getUTCDate();
      return dayA - dayB;
    });
  };

  const getSortedMembersByBirthMonth = () => {
    return [...allMembers].sort((a, b) => {
      if (!a.birthDate) return 1;
      if (!b.birthDate) return -1;
      const monthA = new Date(a.birthDate).getUTCMonth();
      const monthB = new Date(b.birthDate).getUTCMonth();

      if (monthA !== monthB) return monthA - monthB;

      const dayA = new Date(a.birthDate).getUTCDate();
      const dayB = new Date(b.birthDate).getUTCDate();
      return dayA - dayB;
    });
  };

  const monthNames = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

  const isAdmin = user?.role === 'admin' || user?.email === ADMIN_EMAIL;

  if (isLoading) return (
    <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-6">
      <Loader2 className="text-yellow-500 animate-spin" size={48} />
      <p className="text-yellow-500 font-oswald font-black uppercase tracking-widest animate-pulse italic">Sincronizando Radar...</p>
    </div>
  );

  return (
