                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              )}
            </div>
            <footer className="mt-16 py-8 text-center border-t border-zinc-900/50">
              <p className="text-[10px] italic text-zinc-600 uppercase tracking-widest">Developed by Antunes Rider</p>
            </footer>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface User {
  id: string;
  name: string;
  email: string;
  bikeModel?: string;
  avatar?: string;
  birthDate?: string;
  associationType?: 'PILOTO' | 'ESPOSA' | 'ASSOCIADO';
  role?: 'admin' | 'member';
}

export interface RoutePoint {
  lat: number;
  lng: number;
  timestamp: number;
}

export interface Route {
  id: string;
  user_id?: string;
  title: string;
  description: string;
  distance: string;
  difficulty: 'Fácil' | 'Moderada' | 'Difícil' | 'Lendária';
  points: RoutePoint[];
  status: 'planejada' | 'concluída' | 'ativa';
  thumbnail?: string;
  isOfficial?: boolean;
}

export type View = 'home' | 'explorer' | 'my-routes' | 'profile' | 'tracking' | 'gallery' | 'clubhouse' | 'admin';

