  const videoRef = useRef<HTMLIFrameElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const syncInProgress = useRef(false);

  useEffect(() => {
    let mounted = true;

    // Timer de segurança para forçar o carregamento mesmo se o Supabase demorar
    const safetyTimer = setTimeout(() => {
      if (mounted && isLoading) {
        console.warn("Forçando encerramento do loading via safety timer.");
        setIsLoading(false);
      }
    }, 5000);

    const checkInitialSession = async () => {
      try {
        const { data: { session }, error } = await supabase.auth.getSession();
        if (mounted) {
          if (session?.user) {
            await syncUserData(session.user);
          } else {
            setIsLoading(false);
          }
        }
      } catch (err) {
        console.error("Erro no checkInitialSession:", err);
        if (mounted) setIsLoading(false);
      }
    };

    checkInitialSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;
      if (session?.user) {
        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      clearTimeout(safetyTimer);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    if (syncInProgress.current) return;
    syncInProgress.current = true;

    try {
      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      const userData: User = {
        id: authUser.id,
        name: profileData?.name || authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        bikeModel: profileData?.bike_model || 'Não informado',
        avatar: profileData?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        birthDate: profileData?.birth_date || '',
        associationType: profileData?.association_type || undefined,
        role: (profileData?.role as 'admin' | 'member') || (authUser.email === ADMIN_EMAIL ? 'admin' : 'member')
      };

      setUser(userData);
      setEditForm({
        name: userData.name,
        bikeModel: userData.bikeModel || '',
        avatar: userData.avatar || '',
        birthDate: userData.birthDate || '',
        associationType: userData.associationType || ''
      });
      setIsAuthenticated(true);
    } catch (err) {
      console.error("Erro na sincronização:", err);
    } finally {
      setIsLoading(false);
      syncInProgress.current = false;
    }
  };

  const fetchMembers = async () => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('id, name, avatar_url, birth_date, bike_model, association_type')
        .order('name', { ascending: true });

      if (error) throw error;
      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: ''
        })));
      }
