    try {
      const { data, error } = await supabase
        .from('routes')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: r.points,
          status: r.status,
          thumbnail: r.thumbnail,
