const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [allMembers, setAllMembers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [editForm, setEditForm] = useState({ name: '', bikeModel: '', avatar: '', birthDate: '', associationType: '' as any });
  const [isMuted, setIsMuted] = useState(true);
  const videoRef = useRef<HTMLIFrameElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const syncInProgress = useRef(false);

  useEffect(() => {
    let mounted = true;

    // Timer de segurança estendido para garantir que o radar nunca trave
    const safetyTimer = setTimeout(() => {
      if (mounted && isLoading) {
        setIsLoading(false);
      }
    }, 10000);

    // Confiamos exclusivamente no onAuthStateChange para gerenciar a sessão
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (!mounted) return;

      if (session?.user) {
        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      clearTimeout(safetyTimer);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    if (syncInProgress.current) return;
    syncInProgress.current = true;

    try {
      // Passo 1: Definir dados básicos para liberar a interface imediatamente
      const basicUserData: User = {
        id: authUser.id,
        name: authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        avatar: authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };

      setUser(basicUserData);
      setIsAuthenticated(true);

      // Passo 2: Tentar carregar dados enriquecidos do perfil
      const { data: profileData, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      if (profileData && !error) {
        const fullUserData: User = {
          ...basicUserData,
          name: profileData.name || basicUserData.name,
          bikeModel: profileData.bike_model || 'Não informado',
          avatar: profileData.avatar_url || basicUserData.avatar,
          birthDate: profileData.birth_date || '',
          associationType: profileData.association_type || undefined,
          role: profileData.role || basicUserData.role
        };

        setUser(fullUserData);
        setEditForm({
          name: fullUserData.name,
          bikeModel: fullUserData.bikeModel || '',
          avatar: fullUserData.avatar || '',
          birthDate: fullUserData.birthDate || '',
          associationType: fullUserData.associationType || ''
        });
      }
    } catch (err) {
      console.error("Erro na sincronização:", err);
    } finally {
      setIsLoading(false);
      syncInProgress.current = false;
    }
  };

  const fetchMembers = async () => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('id, name, avatar_url, birth_date, bike_model, association_type')
        .order('name', { ascending: true });

      if (error) throw error;
      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: ''
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar membros:", err);
    }
  };

  const fetchRoutes = async () => {
    try {
      const { data, error } = await supabase
        .from('routes')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: r.points,
          status: r.status,
          thumbnail: r.thumbnail,
          isOfficial: r.is_official
        })));
      }
