        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setIsLoading(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    try {
      const basicUserData: User = {
        id: authUser.id,
        name: authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        avatar: authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };

      const { data: profileData } = await supabase.from('profiles').select('*').eq('id', authUser.id).maybeSingle();

      if (profileData) {
        const fullUser = { 
          ...basicUserData, 
          name: profileData.name || basicUserData.name, 
          bikeModel: profileData.bike_model, 
          avatar: profileData.avatar_url || basicUserData.avatar, 
          birthDate: profileData.birth_date, 
          associationType: profileData.association_type 
        };
        setUser(fullUser);
        setEditForm({ 
          name: fullUser.name, 
          bikeModel: fullUser.bikeModel || '', 
          avatar: fullUser.avatar || '', 
          birthDate: fullUser.birthDate || '', 
          associationType: fullUser.associationType || '' 
        });
      } else {
        setUser(basicUserData);
      }
      setIsAuthenticated(true);
    } catch (err) {
      console.error("Erro na sincronização:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const fetchMembers = async () => {
    const { data } = await supabase.from('profiles').select('*').order('name');
    if (data) {
      setAllMembers(data.map(m => ({ 
        id: m.id, 
        name: m.name, 
        avatar: m.avatar_url, 
        birthDate: m.birth_date, 
        bikeModel: m.bike_model, 
        associationType: m.association_type, 
        email: '' 
      })));
    }
  };

  const fetchRoutes = async () => {
    const { data } = await supabase.from('routes').select('*').order('created_at', { ascending: false });
    if (data) {
      setRoutes(data.map(r => ({ 
        id: r.id, 
        user_id: r.user_id, 
        title: r.title, 
        description: r.description, 
        distance: r.distance, 
        difficulty: r.difficulty, 
        points: r.points, 
        status: r.status, 
        thumbnail: r.thumbnail, 
        isOfficial: r.is_official 
      })));
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { error } = await supabase.auth.signInWithPassword(loginForm);
    if (error) {
      alert("Acesso negado: " + error.message);
      setIsLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;
    await supabase.from('routes').insert([{ 
      ...newRoute, 
      user_id: user.id, 
      is_official: user.role === 'admin' 
    }]);
    fetchRoutes();
  };

  const isAdmin = user?.role === 'admin' || user?.email === ADMIN_EMAIL;

  if (isLoading) return (
    <div className="min-h-screen bg-black flex items-center justify-center">
      <Loader2 className="text-yellow-500 animate-spin" size={48} />
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#121212] text-zinc-300">
      <Sidebar user={user} currentView={currentView} setView={setView} onLogout={handleLogout} />

      <main className="flex-1 p-5 md:p-12 pb-32 md:pb-12 max-w-[1400px] mx-auto w-full overflow-y-auto custom-scrollbar">
        {!isAuthenticated && !['home', 'clubhouse'].includes(currentView) ? (
          <div className="flex flex-col items-center justify-center h-full min-h-[80vh]">
            <div className="w-full max-w-md bg-zinc-900 p-10 rounded-[2.5rem] border border-zinc-800 shadow-2xl">
              <img 
                src={LAMA_LOGO_URL} 
                alt="Logo" 
                className="w-24 h-24 mx-auto mb-8 object-contain"
                onError={(e) => { (e.target as HTMLImageElement).src = LAMA_LOGO_URL + '?v=2'; }}
              />
              <h2 className="text-2xl font-oswald text-center text-white font-bold uppercase mb-8">Sede Virtual</h2>
              <form onSubmit={handleLogin} className="space-y-4">
                <input 
                  type="email" 
                  placeholder="Email" 
                  className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white outline-none focus:border-yellow-500" 
                  onChange={e => setLoginForm({...loginForm, email: e.target.value})} 
                />
                <input 
                  type="password" 
                  placeholder="Senha" 
                  className="w-full bg-black border border-zinc-800 p-4 rounded-2xl text-white outline-none focus:border-yellow-500" 
                  onChange={e => setLoginForm({...loginForm, password: e.target.value})} 
                />
                <button type="submit" className="w-full bg-yellow-500 text-black py-4 rounded-2xl font-black uppercase hover:bg-yellow-400 transition-colors">Entrar</button>
              </form>
            </div>
          </div>
        ) : (
