                  />
                  <div>
                    <h1 className="text-4xl md:text-6xl font-oswald font-black uppercase italic text-white">L.A.M.A. <span className="text-yellow-500">Aparecida</span></h1>
                    <p className="text-zinc-500 font-bold uppercase tracking-widest text-[10px] md:text-xs">Capítulo Fundado em 10/2022</p>
                  </div>
