        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    try {
      const basicUserData: User = {
        id: authUser.id,
        name: authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        avatar: authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };

      setUser(basicUserData);
      setIsAuthenticated(true);

      const { data: profileData, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      if (profileData && !error) {
        const fullUserData: User = {
          ...basicUserData,
          name: profileData.name || basicUserData.name,
          bikeModel: profileData.bike_model || 'Não informado',
          avatar: profileData.avatar_url || basicUserData.avatar,
          birthDate: profileData.birth_date || '',
          associationType: profileData.association_type || undefined,
          role: profileData.role || basicUserData.role
        };

        setUser(fullUserData);
        setEditForm({
          name: fullUserData.name,
          bikeModel: fullUserData.bikeModel || '',
          avatar: fullUserData.avatar || '',
          birthDate: fullUserData.birthDate || '',
          associationType: fullUserData.associationType || ''
        });
      }
    } catch (err) {
      console.error("Erro na sincronização:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const fetchMembers = async () => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('id, name, avatar_url, birth_date, bike_model, association_type')
        .order('name', { ascending: true });

      if (error) throw error;
      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: ''
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar membros:", err);
    }
  };

  const fetchRoutes = async () => {
    try {
      const { data, error } = await supabase
        .from('routes')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: r.points,
          status: r.status,
          thumbnail: r.thumbnail,
          isOfficial: r.is_official
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar rotas:", err);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword(loginForm);
      if (error) {
        alert("Acesso negado: " + error.message);
        setIsLoading(false);
      }
    } catch (err: any) {
      alert("Erro inesperado no login.");
      setIsLoading(false);
    }
  };

  // Fixed the property access from birth to birthDate and completed the function
  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);

    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate // Fixed: changed from birth to birthDate
      });
      if (error) throw error;
      await syncUserData({ id: user.id, email: user.email });
      alert("Perfil atualizado!");
    } catch (err: any) {
      console.error(err);
      alert("Erro ao atualizar perfil.");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;
    try {
      const { error } = await supabase.from('routes').insert({
        user_id: user.id,
        title: newRoute.title,
        description: newRoute.description,
        distance: newRoute.distance,
        difficulty: newRoute.difficulty,
        points: newRoute.points,
        status: newRoute.status,
        thumbnail: newRoute.thumbnail
      });
      if (error) throw error;
      fetchRoutes();
      setView('my-routes');
    } catch (err) {
      console.error("Erro ao salvar rota:", err);
    }
  };

  const loadInsights = async (routeName: string) => {
    const res = await getRouteInsights(routeName, "Goiânia, Brasil");
    setInsights(res);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#0a0a0f] flex flex-col items-center justify-center gap-6">
        <div className="relative">
          <div className="w-24 h-24 border-4 border-yellow-500/20 border-t-yellow-500 rounded-full animate-spin"></div>
          <img src={LAMA_LOGO_URL} alt="LAMA" className="absolute inset-0 m-auto w-12 h-12 object-contain" />
        </div>
        <p className="text-yellow-500 font-oswald font-black uppercase tracking-[0.3em] animate-pulse">Iniciando Sistemas...</p>
      </div>
    );
  }

  // Added missing return statement for App component to fix the FC type error
  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-yellow-500/30">
      {!isAuthenticated ? (
        <div className="min-h-screen flex items-center justify-center p-4 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-zinc-900 via-black to-black">
          <form onSubmit={handleLogin} className="w-full max-w-md bg-[#0a0a0f] border border-zinc-900 p-10 rounded-[2.5rem] shadow-2xl space-y-8">
            <div className="text-center space-y-4">
              <img src={LAMA_LOGO_URL} alt="LAMA" className="w-24 h-24 mx-auto mb-6" />
