                value={loginForm.email}
                onChange={e => setLoginForm({...loginForm, email: e.target.value})}
                required
              />
              <input
                type="password"
                placeholder="SENHA"
                className="w-full bg-zinc-950 border border-zinc-900 px-6 py-4 rounded-2xl focus:border-yellow-500 outline-none transition-all font-mono text-sm text-white"
                value={loginForm.password}
                onChange={e => setLoginForm({...loginForm, password: e.target.value})}
                required
