                      {iconicRoutes.slice(0, 2).map(route => (
                        <div key={route.id} className="p-4 bg-black/40 border border-zinc-900 rounded-2xl flex items-center gap-4 hover:border-yellow-500/30 transition-all cursor-pointer">
