                  </div>
                </header>

                <form onSubmit={handleUpdateProfile} className="bg-zinc-950 border border-zinc-900 p-8 md:p-12 rounded-[3rem] space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-zinc-600 text-[9px] font-bold uppercase tracking-[0.2em] ml-2">Nome Completo</label>
                      <input 
                        type="text" 
                        className="w-full bg-zinc-900 border border-zinc-800 px-6 py-4 rounded-2xl focus:border-yellow-500 outline-none transition-all font-oswald font-bold uppercase text-sm italic text-white"
                        value={editForm.name}
                        onChange={e => setEditForm({...editForm, name: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-zinc-600 text-[9px] font-bold uppercase tracking-[0.2em] ml-2">Sua Máquina</label>
                      <input 
                        type="text" 
                        className="w-full bg-zinc-900 border border-zinc-800 px-6 py-4 rounded-2xl focus:border-yellow-500 outline-none transition-all font-oswald font-bold uppercase text-sm italic text-white"
                        value={editForm.bikeModel}
                        onChange={e => setEditForm({...editForm, bikeModel: e.target.value})}
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-zinc-600 text-[9px] font-bold uppercase tracking-[0.2em] ml-2">Data de Nascimento</label>
                    <input 
                      type="date" 
                      className="w-full bg-zinc-900 border border-zinc-800 px-6 py-4 rounded-2xl focus:border-yellow-500 outline-none transition-all font-mono text-sm uppercase text-white"
                      value={editForm.birthDate}
                      onChange={e => setEditForm({...editForm, birthDate: e.target.value})}
                    />
                  </div>

                  <button 
                    disabled={isUpdating}
                    className="w-full bg-yellow-500 hover:bg-yellow-400 disabled:bg-zinc-800 text-black font-black py-5 rounded-2xl uppercase text-xs tracking-widest transition-all flex items-center justify-center gap-3"
                  >
                    {isUpdating ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                    Salvar Alterações
                  </button>
                </form>
              </div>
            )}
          </main>
        </div>
      )}
    </div>
  );
};

export default App;

