  "https://images.unsplash.com/photo-1558981285-6f0c94958bb6?q=80&w=800",
  "https://images.unsplash.com/photo-1558981359-219d6364c9c8?q=80&w=800",
  "https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?q=80&w=800"
];

const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [allMembers, setAllMembers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session?.user) {
        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setIsLoading(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    try {
      const basicUserData: User = {
        id: authUser.id,
        name: authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        avatar: authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };

      const { data: profileData } = await supabase.from('profiles').select('*').eq('id', authUser.id).maybeSingle();

      if (profileData) {
        setUser({ 
          ...basicUserData, 
          name: profileData.name || basicUserData.name, 
          bikeModel: profileData.bike_model, 
          avatar: profileData.avatar_url || basicUserData.avatar,
          role: profileData.role || basicUserData.role
        });
      } else {
        setUser(basicUserData);
      }
      setIsAuthenticated(true);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const fetchMembers = async () => {
    const { data } = await supabase.from('profiles').select('*').order('name');
    if (data) setAllMembers(data.map(m => ({ id: m.id, name: m.name, avatar: m.avatar_url, email: '' })));
  };

  const fetchRoutes = async () => {
    const { data } = await supabase.from('routes').select('*').order('created_at', { ascending: false });
    if (data) setRoutes(data.map(r => ({ ...r, points: r.points || [] })));
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { error } = await supabase.auth.signInWithPassword(loginForm);
    if (error) {
      alert("Acesso negado: " + error.message);
      setIsLoading(false);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;
    await supabase.from('routes').insert([{ ...newRoute, user_id: user.id }]);
    fetchRoutes();
    setView('my-routes');
  };

  if (isLoading) return <div className="min-h-screen bg-black flex items-center justify-center"><Loader2 className="text-yellow-500 animate-spin" size={48} /></div>;

