];

const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [allMembers, setAllMembers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [insights, setInsights] = useState<any>(null);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [editForm, setEditForm] = useState<Partial<User>>({ name: '', bikeModel: '', avatar: '', birthDate: '', associationType: undefined });
  const [isMuted, setIsMuted] = useState(true);

  const videoRef = useRef<HTMLIFrameElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const syncInProgress = useRef(false);

  useEffect(() => {
    let mounted = true;

    const safetyTimer = setTimeout(() => {
      if (mounted && isLoading) setIsLoading(false);
    }, 8000);

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
      if (!mounted) return;
      if (session?.user) {
        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      clearTimeout(safetyTimer);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    if (syncInProgress.current) return;
    syncInProgress.current = true;

    try {
      const basicUserData: User = {
        id: authUser.id,
        name: authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        avatar: authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };

      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      const finalUser: User = profileData ? {
        ...basicUserData,
        name: profileData.name || basicUserData.name,
        bikeModel: profileData.bike_model || 'Não informado',
        avatar: profileData.avatar_url || basicUserData.avatar,
        birthDate: profileData.birth_date || '',
        associationType: profileData.association_type || undefined,
        role: profileData.role || basicUserData.role
      } : basicUserData;

      setUser(finalUser);
      setEditForm({
        name: finalUser.name,
        bikeModel: finalUser.bikeModel,
        avatar: finalUser.avatar,
        birthDate: finalUser.birthDate,
        associationType: finalUser.associationType
      });
      setIsAuthenticated(true);
    } catch (err) {
      console.error("Sync Error:", err);
    } finally {
      setIsLoading(false);
      syncInProgress.current = false;
    }
  };

  const fetchMembers = async () => {
    try {
      const { data } = await supabase
        .from('profiles')
        .select('id, name, avatar_url, birth_date, bike_model, association_type')
        .order('name', { ascending: true });

      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: ''
        })));
      }
    } catch (err) {
      console.error("Fetch Members Error:", err);
    }
  };

  const fetchRoutes = async () => {
    try {
      const { data } = await supabase
        .from('routes')
        .select('*')
        .order('created_at', { ascending: false });

      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: r.points || [],
          status: r.status,
          thumbnail: r.thumbnail,
          isOfficial: r.is_official
        })));
      }
    } catch (err) {
      console.error("Fetch Routes Error:", err);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { error } = await supabase.auth.signInWithPassword(loginForm);
    if (error) {
      alert("Acesso negado: " + error.message);
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);

    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate || null,
        association_type: editForm.associationType || null,
        updated_at: new Date().toISOString()
      });

      if (error) throw error;
      setUser({ ...user, ...editForm });
      setIsEditingProfile(false);
      fetchMembers();
      alert("Perfil atualizado!");
    } catch (err: any) {
      alert("Erro ao atualizar: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1.5 * 1024 * 1024) {
        alert("A imagem deve ter no máximo 1.5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;
    const { error } = await supabase.from('routes').insert([{
      id: newRoute.id,
      user_id: user.id,
      title: newRoute.title,
      description: newRoute.description,
      distance: newRoute.distance,
      difficulty: newRoute.difficulty,
      points: newRoute.points,
      status: newRoute.status,
      thumbnail: newRoute.thumbnail,
      is_official: user.role === 'admin'
    }]);

    if (error) alert("Erro ao salvar: " + error.message);
    else fetchRoutes();
  };

  const fetchInsights = async (route: Route) => {
    setIsUpdating(true);
    try {
      const data = await getRouteInsights(route.title, "Goiânia, GO");
      setInsights({ ...data, routeTitle: route.title });
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setIsUpdating(false);
    }
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: [] }), '*');
      setIsMuted(!isMuted);
    }
  };

  const handleFullscreen = () => {
    if (videoContainerRef.current) {
      if (document.fullscreenElement) document.exitFullscreen();
