const ADMIN_EMAIL = 'lama.aparecidabr@gmail.com';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setView] = useState<View>('home');
  const [user, setUser] = useState<User | null>(null);
  const [routes, setRoutes] = useState<Route[]>([]);
  const [allMembers, setAllMembers] = useState<User[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [insights, setInsights] = useState<any>(null);

  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [editForm, setEditForm] = useState<Partial<User>>({ name: '', bikeModel: '', avatar: '', birthDate: '', associationType: undefined });
  const [isMuted, setIsMuted] = useState(true);

  const videoRef = useRef<HTMLIFrameElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const syncInProgress = useRef(false);

  useEffect(() => {
    let mounted = true;

    const safetyTimer = setTimeout(() => {
      if (mounted && isLoading) setIsLoading(false);
    }, 8000);

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
      if (!mounted) return;
      if (session?.user) {
        await syncUserData(session.user);
      } else {
        setIsAuthenticated(false);
        setUser(null);
        setIsLoading(false);
      }
    });

    return () => {
      mounted = false;
      clearTimeout(safetyTimer);
      subscription.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (isAuthenticated) {
      fetchRoutes();
      fetchMembers();
    }
  }, [isAuthenticated]);

  const syncUserData = async (authUser: any) => {
    if (syncInProgress.current) return;
    syncInProgress.current = true;

    try {
      const basicUserData: User = {
        id: authUser.id,
        name: authUser.user_metadata?.name || 'Membro L.A.M.A.',
        email: authUser.email || '',
        avatar: authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };

      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .maybeSingle();

      const finalUser: User = profileData ? {
        ...basicUserData,
        name: profileData.name || basicUserData.name,
        bikeModel: profileData.bike_model || 'Não informado',
        avatar: profileData.avatar_url || basicUserData.avatar,
        birthDate: profileData.birth_date || '',
        associationType: profileData.association_type || undefined,
        role: profileData.role || basicUserData.role
      } : basicUserData;

      setUser(finalUser);
      setEditForm({
        name: finalUser.name,
        bikeModel: finalUser.bikeModel,
        avatar: finalUser.avatar,
        birthDate: finalUser.birthDate,
        associationType: finalUser.associationType
      });
      setIsAuthenticated(true);
    } catch (err) {
      console.error("Sync Error:", err);
    } finally {
      setIsLoading(false);
      syncInProgress.current = false;
    }
  };

  const fetchMembers = async () => {
    try {
      const { data } = await supabase
        .from('profiles')
        .select('id, name, avatar_url, birth_date, bike_model, association_type')
        .order('name', { ascending: true });

      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: ''
        })));
      }
    } catch (err) {
      console.error("Fetch Members Error:", err);
    }
  };

  const fetchRoutes = async () => {
    try {
      const { data } = await supabase
        .from('routes')
        .select('*')
        .order('created_at', { ascending: false });

      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: r.points || [],
          status: r.status,
          thumbnail: r.thumbnail,
          isOfficial: r.is_official
        })));
      }
    } catch (err) {
      console.error("Fetch Routes Error:", err);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    const { error } = await supabase.auth.signInWithPassword(loginForm);
    if (error) {
      alert("Acesso negado: " + error.message);
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);

    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birth_date || null,
        association_type: editForm.association_type || null,
        updated_at: new Date().toISOString()
      });

      if (error) throw error;
      setUser({ ...user, ...editForm });
      setIsEditingProfile(false);
      fetchMembers();
      alert("Perfil atualizado!");
    } catch (err: any) {
      alert("Erro ao atualizar: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1.5 * 1024 * 1024) {
        alert("A imagem deve ter no máximo 1.5MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;
    const { error } = await supabase.from('routes').insert([{
      id: newRoute.id,
      user_id: user.id,
      title: newRoute.title,
      description: newRoute.description,
      distance: newRoute.distance,
      difficulty: newRoute.difficulty,
      points: newRoute.points,
      status: newRoute.status,
      thumbnail: newRoute.thumbnail,
      is_official: user.role === 'admin'
    }]);

    if (error) alert("Erro ao salvar: " + error.message);
    else fetchRoutes();
  };

  const fetchInsights = async (route: Route) => {
    setIsUpdating(true);
    try {
      const data = await getRouteInsights(route.title, "Goiânia, GO");
      setInsights({ ...data, routeTitle: route.title });
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setIsUpdating(false);
    }
  };

  const toggleMute = () => {
    if (videoRef.current?.contentWindow) {
      const command = isMuted ? 'unMute' : 'mute';
      videoRef.current.contentWindow.postMessage(JSON.stringify({ event: 'command', func: command, args: [] }), '*');
      setIsMuted(!isMuted);
    }
  };

  const handleFullscreen = () => {
    if (videoContainerRef.current) {
      if (document.fullscreenElement) document.exitFullscreen();
      else videoContainerRef.current.requestFullscreen();
    }
  };

  const birthdays = useMemo(() => {
    const currentMonth = new Date().getUTCMonth();
    const nextMonth = (currentMonth + 1) % 12;

    const filterByMonth = (month: number) => allMembers
      .filter(m => m.birthDate && new Date(m.birthDate).getUTCMonth() === month)
      .sort((a, b) => new Date(a.birthDate!).getUTCDate() - new Date(b.birthDate!).getUTCDate());

    return {
      current: filterByMonth(currentMonth),
      next: filterByMonth(nextMonth)
    };
  }, [allMembers]);

  const isAdmin = user?.role === 'admin' || user?.email === ADMIN_EMAIL;

  if (isLoading) return (
    <div className="min-h-screen bg-[#0a0a0f] flex flex-col items-center justify-center gap-6">
      <Loader2 className="text-yellow-500 animate-spin" size={48} />
      <p className="text-yellow-500 font-oswald font-black uppercase tracking-[0.3em] animate-pulse italic">Iniciando Sistemas...</p>
    </div>
  );

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-[#121212] text-zinc-300 selection:bg-yellow-500/30">
      <Sidebar user={user} currentView={currentView} setView={setView} onLogout={() => supabase.auth.signOut()} />

      <main className="flex-1 p-5 md:p-12 pb-32 md:pb-12 max-w-[1400px] mx-auto w-full overflow-y-auto custom-scrollbar flex flex-col">
        {!isAuthenticated && !['home', 'clubhouse'].includes(currentView) ? (
          <div className="flex-1 flex flex-col items-center justify-center">
            <div className="w-full max-w-md bg-zinc-900 border border-zinc-800 p-8 rounded-[2.5rem] shadow-2xl">
              <div className="text-center mb-10">
                <img src={LAMA_LOGO_URL} alt="LAMA" className="w-20 h-20 mx-auto mb-6 object-contain" />
                <h2 className="text-3xl font-oswald text-white font-black uppercase italic tracking-tighter">Sede Virtual</h2>
              </div>
              <form onSubmit={handleLogin} className="space-y-4">
                <input type="email" required className="w-full bg-black border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none focus:border-yellow-500/50" placeholder="Email" value={loginForm.email} onChange={e => setLoginForm({...loginForm, email: e.target.value})} />
                <input type="password" required className="w-full bg-black border border-zinc-800 text-white px-6 py-4 rounded-2xl outline-none focus:border-yellow-500/50" placeholder="Senha" value={loginForm.password} onChange={e => setLoginForm({...loginForm, password: e.target.value})} />
                <button type="submit" className="w-full bg-yellow-500 hover:bg-yellow-400 text-black py-5 rounded-2xl font-black uppercase flex items-center justify-center gap-3 transition-colors">Entrar <Zap size={16} /></button>
              </form>
            </div>
          </div>
        ) : (
          <div className="animate-in fade-in duration-700 flex-1">
            {currentView === 'home' && (
              <div className="space-y-8">
                <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-zinc-900 pb-12">
                  <div className="flex items-center gap-10">
                    <div className="relative group shrink-0">
                      <div className="absolute inset-0 bg-yellow-500/10 blur-3xl rounded-full scale-150 opacity-0 group-hover:opacity-100 transition-all duration-700"></div>
                      <img src={LAMA_LOGO_URL} alt="Logo" className="relative w-28 h-28 object-contain filter drop-shadow-[0_0_15px_rgba(234,179,8,0.2)]" />
                    </div>
                    <div>
