              )}
            </div>
            <footer className="mt-16 py-8 text-center border-t border-zinc-900/50">
              <p className="text-[10px] italic text-zinc-600 uppercase tracking-widest">Developed by Antunes Rider</p>
            </footer>
          </div>
        )}
      </main>
    </div>
  );
};

