    } catch (error) {
      console.error("Erro no briefing:", error);
    } finally {
      setIsUpdating(false);
    }
  };

  const handleLogout = async () => {
    setIsLoading(true);
    try {
      await supabase.auth.signOut();
    } catch (err) {
      console.error("Erro ao encerrar sessão no servidor:", err);
    } finally {
