        email: authUser.email || '',
        avatar: profileData?.avatar_url || authUser.user_metadata?.avatar_url || `https://api.dicebear.com/7.x/avataaars/svg?seed=${authUser.id}`,
        bikeModel: profileData?.bike_model || 'Não informado',
