        alert("Acesso negado: " + error.message);
        setIsLoading(false);
      }
    } catch (err: any) {
      alert("Erro inesperado no login.");
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);
    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate || null,
        association_type: editForm.associationType || null,
        updated_at: new Date().toISOString()
      });
      if (error) throw error;
      setUser({ ...user, ...editForm });
      setIsEditingProfile(false);
      fetchMembers();
      alert("Perfil atualizado com sucesso!");
    } catch (err: any) {
      alert("Erro ao atualizar perfil: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handlePasswordChange = async () => {
    const newPassword = window.prompt("Digite sua nova senha (mínimo 6 caracteres):");
    if (newPassword && newPassword.length >= 6) {
      setIsUpdating(true);
      try {
        const { error } = await supabase.auth.updateUser({ password: newPassword });
        if (error) throw error;
        alert("Senha alterada com sucesso!");
      } catch (err: any) {
        alert("Erro ao alterar senha: " + err.message);
      } finally {
        setIsUpdating(false);
      }
    } else if (newPassword) alert("A senha deve conter pelo menos 6 caracteres.");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { alert("A imagem deve ter no máximo 2MB."); return; }
      const reader = new FileReader();
      reader.onloadend = () => setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    if (!user) return;
    setIsUpdating(true);
    try {
      // Otimização de dados (Sampling) para evitar Load failed por tamanho excessivo do payload
      let optimizedPoints = newRoute.points;
      if (optimizedPoints.length > 1500) {
        const samplingRate = Math.ceil(optimizedPoints.length / 1500);
        optimizedPoints = optimizedPoints.filter((_, idx) => idx % samplingRate === 0);
      }

      const { error } = await supabase.from('routes').insert([{
        id: generateUUID(),
        user_id: user.id,
        title: newRoute.title,
        description: newRoute.description,
        distance: newRoute.distance,
        difficulty: newRoute.difficulty,
        points: optimizedPoints,
        status: newRoute.status,
        thumbnail: newRoute.thumbnail || 'https://images.unsplash.com/photo-1558981403-c5f91cbba527?q=80&w=800&auto=format&fit=crop',
        is_official: user.role === 'admin'
      }]);

      if (error) throw error;

      // Atualiza lista local antes da navegação para garantir fluidez
      await fetchRoutes();
      setView('my-routes');
    } catch (err: any) {
      console.error("Erro crítico ao salvar missão:", err);
      alert("Erro ao salvar missão: " + (err.message || "Falha na conexão com o radar. Tente novamente."));
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteRoute = async (routeId: string) => {
