import React, { useState, useEffect, useRef } from 'react';
import { Play, Square, Shield, Radio } from 'lucide-react';
import { RoutePoint, Route } from '../types';
import { MapView } from './MapView';

interface RouteTrackerProps {
  onSave?: (route: Route) => void;
}

const calculateDistance = (p1: RoutePoint, p2: RoutePoint): number => {
  const R = 6371;
  const dLat = (p2.lat - p1.lat) * Math.PI / 180;
  const dLon = (p2.lng - p1.lng) * Math.PI / 180;
  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(p1.lat * Math.PI / 180) * Math.cos(p2.lat * Math.PI / 180) * 
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

export const RouteTracker: React.FC<RouteTrackerProps> = ({ onSave }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [points, setPoints] = useState<RoutePoint[]>([]);
  const pointsRef = useRef<RoutePoint[]>([]);
  const [totalDistance, setTotalDistance] = useState(0);
  const distanceRef = useRef(0);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    let interval: any;
    if (isRecording && startTime) {
      interval = setInterval(() => {
        setElapsed(Math.floor((Date.now() - startTime) / 1000));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isRecording, startTime]);

  const startTracking = () => {
    if (!navigator.geolocation) { 
      alert("GPS não suportado pelo seu navegador."); 
      return; 
    }

    setIsRecording(true);
    setStartTime(Date.now());
    setPoints([]);
    pointsRef.current = [];
    setTotalDistance(0);
    distanceRef.current = 0;

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const firstPoint: RoutePoint = { 
          lat: Number(pos.coords.latitude.toFixed(6)), 
          lng: Number(pos.coords.longitude.toFixed(6)), 
          timestamp: pos.timestamp 
        };
        pointsRef.current = [firstPoint];
        setPoints([firstPoint]);
      },
      (err) => console.debug("Aguardando sinal GPS...", err),
      { enableHighAccuracy: true }
    );

    watchId.current = navigator.geolocation.watchPosition(
      (pos) => {
        if (pos.coords.accuracy > 100) return;

        const newPoint: RoutePoint = { 
          lat: Number(pos.coords.latitude.toFixed(6)), 
          lng: Number(pos.coords.longitude.toFixed(6)), 
          timestamp: pos.timestamp 
        };

        if (pointsRef.current.length > 0) {
          const last = pointsRef.current[pointsRef.current.length - 1];
          const dist = calculateDistance(last, newPoint);

          if (dist > 0.005) {
            distanceRef.current += dist;
            setTotalDistance(distanceRef.current);
            pointsRef.current = [...pointsRef.current, newPoint];
            setPoints([...pointsRef.current]);
          }
        } else {
          pointsRef.current = [newPoint];
          setPoints([newPoint]);
        }
      },
      (error) => {
        console.error("Erro no GPS:", error);
      },
      { 
        enableHighAccuracy: true, 
        timeout: 15000, 
        maximumAge: 0 
      }
    );
  };

  const stopTracking = () => {
    if (watchId.current !== null) {
      navigator.geolocation.clearWatch(watchId.current);
      watchId.current = null;
    }

    const finalPoints = [...pointsRef.current];
    const finalDistance = distanceRef.current;
    const finalElapsed = elapsed;

    if (finalPoints.length < 2) {
      alert("Trajeto insuficiente para gravação. Movimente-se mais um pouco.");
      resetState();
      return;
    }

    if (onSave) {
      onSave({
        id: '', 
        title: `Missão em ${new Date().toLocaleDateString('pt-BR')}`,
        description: `Percurso gravado via L.A.M.A. Sede Virtual. Duração: ${formatTime(finalElapsed)}.`,
        distance: `${finalDistance.toFixed(2)} km`,
        difficulty: finalDistance > 50 ? 'Moderada' : 'Fácil',
        points: finalPoints,
        status: 'concluída'
      });
    }

    resetState();
  };

  const resetState = () => {
    setIsRecording(false);
    setStartTime(null);
    setElapsed(0);
    setPoints([]);
    pointsRef.current = [];
    setTotalDistance(0);
    distanceRef.current = 0;
  };

  const formatTime = (sec: number) => {
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = sec % 60;
    if (h > 0) return `${h}h ${m}m`;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <header>
        <h2 className="text-3xl md:text-5xl font-oswald font-black uppercase text-white italic">Gravar <span className="text-yellow-500">Missão</span></h2>
        <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-widest mt-2">Sistema de Telemetria Satelital Ativo</p>
      </header>
      <div className="flex flex-col lg:grid lg:grid-cols-4 gap-6">
        <div className="lg:col-span-3">
          <MapView points={points} className="h-[250px] md:h-[450px] rounded-[2.5rem] shadow-2xl" isInteractive />
        </div>
        <div className="space-y-6">
          <div className="bg-zinc-950 p-8 rounded-[2.5rem] border border-zinc-900 space-y-6 shadow-xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-5"><Radio size={80} /></div>
             <div className="flex justify-between items-end relative z-10">
               <span className="text-[10px] font-black uppercase text-zinc-600 tracking-widest">Cronômetro</span>
               <span className="text-3xl font-oswald font-black text-white italic leading-none">{formatTime(elapsed)}</span>
             </div>
             <div className="flex justify-between items-end border-t border-zinc-900 pt-6 relative z-10">
               <span className="text-[10px] font-black uppercase text-zinc-600 tracking-widest">Distância</span>
               <span className="text-3xl font-oswald font-black text-yellow-500 italic leading-none">{totalDistance.toFixed(2)} <small className="text-xs uppercase ml-1">km</small></span>
             </div>
          </div>

          {!isRecording ? (
            <button 
              onClick={startTracking} 
              className="w-full bg-yellow-500 hover:bg-yellow-600 text-black py-5 rounded-2xl font-black uppercase text-[11px] flex items-center justify-center gap-3 transition-all shadow-xl shadow-yellow-500/10 active:scale-95"
            >
              <Play size={18} fill="currentColor" /> Iniciar Gravação
            </button>
          ) : (
            <button 
              onClick={stopTracking} 
              className="w-full bg-red-600 hover:bg-red-700 text-white py-5 rounded-2xl font-black uppercase text-[11px] flex items-center justify-center gap-3 animate-pulse shadow-xl shadow-red-600/20 active:scale-95"
            >
              <Square size={18} fill="currentColor" /> Finalizar Missão
            </button>
          )}

          <div className="flex items-center gap-4 bg-zinc-900/40 p-5 rounded-2xl border border-zinc-800">
            <Shield className="text-red-600 shrink-0" size={18} />
            <p className="text-[9px] text-zinc-500 font-bold uppercase italic leading-relaxed">
              Mantenha o aplicativo aberto e a tela ligada para garantir a precisão total do trajeto.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { RoutePoint } from '../types';

interface MapViewProps {
  points: RoutePoint[];
  className?: string;
  isInteractive?: boolean;
}

export const MapView: React.FC<MapViewProps> = ({ points, className = "h-64", isInteractive = false }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<any>(null);
  const polylineLayer = useRef<any>(null);
  const startMarker = useRef<any>(null);
  const endMarker = useRef<any>(null);
  const currentPosMarker = useRef<any>(null);

  useEffect(() => {
    const L = (window as any).L;
    if (!L || !mapRef.current || leafletMap.current) return;

    leafletMap.current = L.map(mapRef.current, {
      zoomControl: isInteractive,
      dragging: isInteractive,
      scrollWheelZoom: isInteractive,
      attributionControl: false,
    }).setView([-16.7908906, -49.2311547], 15);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 19,
    }).addTo(leafletMap.current);

    // Forçar o mapa a reconhecer o tamanho correto do container
    setTimeout(() => {
      if (leafletMap.current) leafletMap.current.invalidateSize();
    }, 100);

    return () => {
      if (leafletMap.current) {
        leafletMap.current.remove();
        leafletMap.current = null;
      }
    };
  }, [isInteractive]);

  useEffect(() => {
    const L = (window as any).L;
    if (!L || !leafletMap.current) return;

    if (!points || points.length === 0) {
      if (polylineLayer.current) leafletMap.current.removeLayer(polylineLayer.current);
      if (startMarker.current) leafletMap.current.removeLayer(startMarker.current);
      if (endMarker.current) leafletMap.current.removeLayer(endMarker.current);
      if (currentPosMarker.current) leafletMap.current.removeLayer(currentPosMarker.current);
      return;
    }

    const latLngs = points.map(p => [p.lat, p.lng]).filter(coords => !isNaN(coords[0]) && !isNaN(coords[1]));

    if (latLngs.length > 0) {
      // Atualizar ou Criar Polyline
      if (polylineLayer.current) {
        polylineLayer.current.setLatLngs(latLngs);
      } else {
        polylineLayer.current = L.polyline(latLngs, { color: '#eab308', weight: 4, opacity: 0.8 }).addTo(leafletMap.current);
      }

      // Atualizar Marcadores
      const latestPoint = latLngs[latLngs.length - 1];

      if (latLngs.length === 1) {
        if (!startMarker.current) {
          startMarker.current = L.circleMarker(latestPoint, { radius: 6, color: '#eab308', fillOpacity: 1 }).addTo(leafletMap.current);
        } else {
          startMarker.current.setLatLng(latestPoint);
        }
        leafletMap.current.panTo(latestPoint);
      } else {
        // Se estivermos gravando (não interativo) ou se for um novo trajeto, seguimos o rastro
        if (!isInteractive) {
           leafletMap.current.panTo(latestPoint);
        }

        // Marcador de posição atual/final
        if (!endMarker.current) {
          endMarker.current = L.circleMarker(latestPoint, { radius: 5, color: '#ef4444', fillOpacity: 1, weight: 2 }).addTo(leafletMap.current);
        } else {
          endMarker.current.setLatLng(latestPoint);
        }

        // Fit bounds apenas no início ou se o trajeto crescer muito
        if (latLngs.length % 20 === 0 && isInteractive) {
          leafletMap.current.fitBounds(polylineLayer.current.getBounds(), { padding: [30, 30] });
        }
      }
    }
  }, [points, isInteractive]);

  return (
    <div ref={mapRef} className={`rounded-xl overflow-hidden border border-zinc-800 ${className}`} />
  );
};

