        role: authUser.email === ADMIN_EMAIL ? 'admin' : 'member'
      };
      setUser(basicUserData);
      setIsAuthenticated(true);
      const { data: profileData, error } = await supabase.from('profiles').select('*').eq('id', authUser.id).maybeSingle();
      if (profileData && !error) {
        const fullUserData: User = {
          ...basicUserData,
          name: profileData.name || basicUserData.name,
          bikeModel: profileData.bike_model || 'Não informado',
          avatar: profileData.avatar_url || basicUserData.avatar,
          birthDate: profileData.birth_date || '',
          associationType: profileData.association_type || undefined,
          role: profileData.role || basicUserData.role
        };
        setUser(fullUserData);
        setEditForm({
          name: fullUserData.name,
          bikeModel: fullUserData.bikeModel || '',
          avatar: fullUserData.avatar || '',
          birthDate: fullUserData.birthDate || '',
          associationType: fullUserData.associationType
        });
      }
    } catch (err) {
      console.error("Erro na sincronização:", err);
    } finally {
      setIsLoading(false);
      syncInProgress.current = false;
    }
  };

  const fetchMembers = async () => {
    try {
      const { data, error } = await supabase.from('profiles').select('id, name, avatar_url, birth_date, bike_model, association_type').order('name', { ascending: true });
      if (error) throw error;
      if (data) {
        setAllMembers(data.map((m: any) => ({
          id: m.id,
          name: m.name,
          avatar: m.avatar_url,
          birthDate: m.birth_date,
          bikeModel: m.bike_model,
          associationType: m.association_type,
          email: ''
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar membros:", err);
    }
  };

  const fetchRoutes = async () => {
    try {
      const { data, error } = await supabase.from('routes').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setRoutes(data.map((r: any) => ({
          id: r.id,
          user_id: r.user_id,
          title: r.title,
          description: r.description,
          distance: r.distance,
          difficulty: r.difficulty,
          points: Array.isArray(r.points) ? r.points : [],
          status: r.status,
          thumbnail: r.thumbnail,
          isOfficial: r.is_official
        })));
      }
    } catch (err) {
      console.error("Erro ao buscar rotas:", err);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword(loginForm);
      if (error) {
        alert("Acesso negado: " + error.message);
        setIsLoading(false);
      }
    } catch (err: any) {
      alert("Erro inesperado no login.");
      setIsLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setIsUpdating(true);
    try {
      const { error } = await supabase.from('profiles').upsert({
        id: user.id,
        name: editForm.name,
        bike_model: editForm.bikeModel,
        avatar_url: editForm.avatar,
        birth_date: editForm.birthDate || null,
        association_type: editForm.associationType || null,
        updated_at: new Date().toISOString()
      });
      if (error) throw error;
      setUser({ ...user, ...editForm });
      setIsEditingProfile(false);
      fetchMembers();
      alert("Perfil atualizado com sucesso!");
    } catch (err: any) {
      alert("Erro ao atualizar perfil: " + err.message);
    } finally {
      setIsUpdating(false);
    }
  };

  const handlePasswordChange = async () => {
    const newPassword = window.prompt("Digite sua nova senha (mínimo 6 caracteres):");
    if (newPassword && newPassword.length >= 6) {
      setIsUpdating(true);
      try {
        const { error } = await supabase.auth.updateUser({ password: newPassword });
        if (error) throw error;
        alert("Senha alterada com sucesso!");
      } catch (err: any) {
        alert("Erro ao alterar senha: " + err.message);
      } finally {
        setIsUpdating(false);
      }
    } else if (newPassword) alert("A senha deve conter pelo menos 6 caracteres.");
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { alert("A imagem deve ter no máximo 2MB."); return; }
      const reader = new FileReader();
      reader.onloadend = () => setEditForm(prev => ({ ...prev, avatar: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const handleSaveRoute = async (newRoute: Route) => {
    // Verificação de segurança da sessão
    const { data: { session } } = await supabase.auth.getSession();
    if (!session || !user) {
      alert("Sua sessão expirou durante a viagem. Faça login novamente para salvar futuras missões.");
      throw new Error("Unauthorized");
    }

    setIsUpdating(true);
    try {
      // Filtrar pontos inválidos ou duplicados
      let validPoints = newRoute.points.filter(p => 
        p && typeof p.lat === 'number' && !isNaN(p.lat) && 
        typeof p.lng === 'number' && !isNaN(p.lng)
      );

      // Otimização agressiva: Limitar a 400 pontos para garantir que o banco processe rápido
      // Isso mantém o formato do trajeto mas reduz o peso do JSON drasticamente
      let optimizedPoints = validPoints;
      if (optimizedPoints.length > 400) {
        const factor = Math.ceil(optimizedPoints.length / 400);
        optimizedPoints = optimizedPoints.filter((_, i) => i % factor === 0 || i === optimizedPoints.length - 1);
      }

      const routePayload = {
        id: generateUUID(),
        user_id: user.id,
        title: newRoute.title.trim() || `Missão em ${new Date().toLocaleDateString()}`,
        description: newRoute.description.trim(),
        distance: newRoute.distance,
        difficulty: newRoute.difficulty,
        points: optimizedPoints,
        status: newRoute.status,
        thumbnail: 'https://images.unsplash.com/photo-1558981403-c5f91cbba527?q=80&w=800&auto=format&fit=crop',
        is_official: user.role === 'admin'
      };

      const { error } = await supabase.from('routes').insert([routePayload]);

      if (error) throw error;

      // Transição imediata de view para liberar o usuário
      setView('my-routes');
      // Atualizar a lista de rotas em segundo plano
      fetchRoutes();

    } catch (err: any) {
      console.error("Erro crítico no salvamento do Mural:", err);
      alert("Falha técnica ao sincronizar com o Mural. Verifique seu sinal de internet.");
      throw err; // Repassa para o RouteTracker parar o Loader
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDeleteRoute = async (routeId: string) => {
    if (!confirm("Deseja realmente excluir esta missão permanentemente?")) return;
    try {
      const { error } = await supabase.from('routes').delete().eq('id', routeId);
      if (error) throw error;
      setRoutes(prev => prev.filter(r => r.id !== routeId));
      if (selectedRoute?.id === routeId) setSelectedRoute(null);
    } catch (err: any) {
      alert("Erro ao excluir missão: " + err.message);
    }
  };

  const fetchInsights = async (route: Route) => {
    setIsUpdating(true);
    try {
