                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {currentView === 'tracking' && <RouteTracker onSave={handleSaveRoute} />}

              {currentView === 'my-routes' && (
                <div className="space-y-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
